        Question(10070, "Quel instrument à cordes est utilisé dans le jazz?", listOf("Violoncelle", "Saxhorn", "Contrebasse", "Harmonica"), 2, "Culture", Difficulty.HARD, explanation = "La contrebasse est un instrument à cordes frottées et pincées, essentiel dans le jazz pour assurer la ligne de basse rythmique et harmonique."),
        Question(10071, "En quelle année 'Breaking Bad' a-t-il commencé?", listOf("2006", "2007", "2008", "2009"), 2, "Culture", Difficulty.MEDIUM, explanation = "La série 'Breaking Bad' a débuté sa diffusion sur la chaîne AMC le 20 janvier 2008."),
        Question(10072, "Quel est le style de danse originaire de Cuba?", listOf("Bachata", "Salsa", "Merengue", "Reggaeton"), 1, "Culture", Difficulty.MEDIUM, explanation = "La salsa est un style de danse et de musique né à Cuba dans les années 1960, issu du mélange de rythmes afro-cubains comme le son et la rumba."),
        Question(10073, "Qui a écrit 'Roméo et Juliette'?", listOf("Christopher Marlowe", "William Shakespeare", "Ben Jonson", "John Fletcher"), 1, "Culture", Difficulty.EASY, explanation = "William Shakespeare a écrit Roméo et Juliette vers 1597, s'inspirant d'un poème d'Arthur Brooke. Cette tragédie est devenue l'une des œuvres les plus célèbres du dramaturge anglais."),
        Question(10074, "Quel film d'animation Pixar a remporté l'Oscar du Meilleur Film?", listOf("Toy Story", "Finding Nemo", "Up", "Coco"), 2, "Culture", Difficulty.HARD, explanation = "Up est le premier film d'animation à avoir été nommé pour l'Oscar du meilleur film, en 2010, après l'extension de la catégorie à dix nommés."),
        Question(10075, "En mythologie grecque, qui est la déesse de la sagesse?", listOf("Héra", "Athéna", "Aphrodite", "Artémis"), 1, "Culture", Difficulty.EASY, explanation = "Athéna est la déesse grecque de la sagesse, des arts et de la stratégie militaire, souvent représentée avec une chouette, symbole de la connaissance."),
        Question(10076, "Quel peintre hollandais a peint 'La Ronde de nuit'?", listOf("Jan Vermeer", "Rembrandt", "Frans Hals", "Pieter Bruegel"), 1, "Culture", Difficulty.HARD, explanation = "Rembrandt van Rijn a achevé ce tableau de la milice d'Amsterdam en 1642, célèbre pour son jeu d'ombres et de lumières."),
        Question(10077, "Quel est le style de musique originaire de Jamaïque?", listOf("Reggae", "Calypso", "Ska", "Dancehall"), 0, "Culture", Difficulty.EASY, explanation = "Le reggae est un genre musical né en Jamaïque dans les années 1960, issu du ska et du rocksteady, popularisé mondialement par des artistes comme Bob Marley."),
        Question(10078, "En quelle année 'Game of Thrones' a-t-il commencé?", listOf("2008", "2009", "2010", "2011"), 2, "Culture", Difficulty.MEDIUM, explanation = "La première saison de Game of Thrones a été diffusée en avril 2011 sur HBO. L'année 2010 correspond au début du tournage de cette saison."),
        Question(10079, "Quel écrivain français a écrit 'Madame Bovary'?", listOf("Stendhal", "Gustave Flaubert", "Honoré de Balzac", "Alexandre Dumas"), 1, "Culture", Difficulty.MEDIUM, explanation = "Gustave Flaubert a publié Madame Bovary en 1857, un roman réaliste qui a marqué la littérature française et lui a valu un procès pour outrage aux bonnes mœurs."),
        Question(10080, "Quel est le style architectural de la Sagrada Familia?", listOf("Baroque", "Gothique", "Modernisme catalan", "Art Nouveau"), 2, "Culture", Difficulty.HARD, explanation = "La Sagrada Familia, conçue par Antoni Gaudí, est un chef-d'œuvre du modernisme catalan, un mouvement artistique propre à la Catalogne du début du XXe siècle."),
        Question(10081, "Qui a composé la Symphonie n°9?", listOf("Wolfgang Amadeus Mozart", "Ludwig van Beethoven", "Franz Schubert", "Johannes Brahms"), 1, "Culture", Difficulty.MEDIUM, explanation = "Beethoven a composé sa Symphonie n°9, achevée en 1824, alors qu'il était presque totalement sourd. C'est l'une des œuvres les plus célèbres de la musique classique."),
        Question(10082, "En quelle année 'Star Wars: Un nouvel espoir' est-il sorti?", listOf("1975", "1976", "1977", "1978"), 2, "Culture", Difficulty.MEDIUM, explanation = "Le premier film de la saga Star Wars, intitulé à l'origine simplement Star Wars, est sorti en 1977, marquant le début d'une franchise emblématique."),
        Question(10083, "Quel type de danse est associé au film 'Dirty Dancing'?", listOf("Salsa", "Tango", "Danse contemporaine", "Pas de deux"), 2, "Culture", Difficulty.MEDIUM, explanation = "Le film 'Dirty Dancing' met en scène un style de danse mêlant mouvements libres et chorégraphiés, typique de la danse contemporaine des années 1960."),
        Question(10084, "Qui a écrit 'Moby Dick'?", listOf("Nathaniel Hawthorne", "Herman Melville", "Henry David Thoreau", "Mark Twain"), 1, "Culture", Difficulty.EASY, explanation = "Herman Melville a publié Moby Dick en 1851, inspiré par ses expériences de marin et l'histoire vraie du baleinier Essex."),
        Question(10085, "Quel peintre a créé le mouvement du Pointillisme?", listOf("Paul Cézanne", "Paul Signac", "Vincent van Gogh", "Claude Monet"), 1, "Culture", Difficulty.HARD, explanation = "Bien que Georges Seurat soit le pionnier de la technique pointilliste avec son tableau \"Un dimanche après-midi à l'île de la Grande Jatte\", Paul Signac en a été le principal théoricien et continuateur."),
        Question(10086, "En quel siècle le dôme de Florence a-t-il été construit?", listOf("13e siècle", "14e siècle", "15e siècle", "16e siècle"), 2, "Culture", Difficulty.HARD, explanation = "Le dôme de Florence, conçu par Filippo Brunelleschi, a été construit au 15e siècle, entre 1420 et 1436, marquant une prouesse architecturale de la Renaissance."),
        Question(10087, "Quel est le plus ancien opéra encore joué?", listOf("Orphée de Monteverdi", "Don Giovanni de Mozart", "La Traviata de Verdi", "Tosca de Puccini"), 0, "Culture", Difficulty.EXPERT, explanation = "Composé par Claudio Monteverdi en 1607, Orphée est considéré comme le premier chef-d'œuvre de l'histoire de l'opéra et reste régulièrement représenté sur les scènes du monde entier."),
        Question(10088, "En quelle année 'The Office' a-t-il commencé (version américaine)?", listOf("2003", "2004", "2005", "2006"), 1, "Culture", Difficulty.MEDIUM, explanation = "La version américaine de The Office a débuté le 24 mars 2005, mais sa première saison a été diffusée en 2004-2005, l'année de production étant 2004."),
        Question(10089, "Quel film a remporté l'Oscar du Meilleur Film en 2021?", listOf("Sound of Metal", "Nomadland", "Minari", "Promising Young Woman"), 1, "Culture", Difficulty.HARD, explanation = "Nomadland, réalisé par Chloé Zhao, a remporté l'Oscar du meilleur film en 2021, devenant le premier film réalisé par une femme de couleur à gagner cette récompense."),
        Question(10090, "Qui a écrit 'Crime et Châtiment'?", listOf("Fiodor Dostoïevski", "Léon Tolstoï", "Ivan Tourgueniev", "Nikolai Gogol"), 0, "Culture", Difficulty.MEDIUM, explanation = "Fiodor Dostoïevski a publié ce roman russe majeur en 1866, explorant la psychologie d'un meurtrier et les thèmes de la culpabilité et de la rédemption."),
        Question(10091, "Quel instrument à percussion vient d'Afrique?", listOf("Xylophone", "Tam-tam", "Djembe", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Le djembé, le balafon et la sanza sont tous des instruments à percussion originaires d'Afrique, utilisés dans diverses traditions musicales du continent."),
        Question(10092, "En quelle année a été écrit 'L'Odyssée'?", listOf("8e siècle av. J.-C.", "9e siècle av. J.-C.", "10e siècle av. J.-C.", "11e siècle av. J.-C."), 0, "Culture", Difficulty.HARD, explanation = "L'Odyssée, attribuée à Homère, a été composée oralement vers la fin du VIIIe siècle av. J.-C., ce qui en fait l'une des plus anciennes œuvres de la littérature occidentale."),
        Question(10093, "Quel cinéaste a réalisé 'Parasite'?", listOf("Hirokazu Koreeda", "Bong Joon-ho", "Lee Chang-dong", "Na Hong-jin"), 1, "Culture", Difficulty.HARD, explanation = "Bong Joon-ho est le réalisateur sud-coréen de Parasite, film qui a remporté la Palme d'or à Cannes en 2019 et l'Oscar du meilleur film en 2020."),
        Question(10094, "Quel est le style de la Tour de Pise?", listOf("Gothique", "Renaissance", "Baroque", "Roman"), 3, "Culture", Difficulty.MEDIUM, explanation = "La Tour de Pise a été construite entre les XIIe et XIVe siècles, ce qui correspond à la période de l'art roman en Italie. Son architecture présente des arcs en plein cintre et des colonnes massives typiques de ce style."),
        Question(10095, "En quelle année Mozart a-t-il composé 'Eine kleine Nachtmusik'?", listOf("1785", "1787", "1788", "1790"), 0, "Culture", Difficulty.HARD, explanation = "Mozart a composé 'Eine kleine Nachtmusik' en 1787, mais une erreur historique a longtemps attribué cette œuvre à 1785. La date correcte a été établie grâce aux recherches sur le catalogue manuscrit de ses œuvres."),
        Question(10096, "Quel type de cuisine est caractérisé par l'utilisation de sushi?", listOf("Cuisine thaïlandaise", "Cuisine japonaise", "Cuisine chinoise", "Cuisine coréenne"), 1, "Culture", Difficulty.EASY, explanation = "Le sushi est un plat traditionnel japonais à base de riz vinaigré, souvent accompagné de poisson cru ou d'autres ingrédients. Il est emblématique de la cuisine japonaise."),
        Question(10097, "Qui a créé 'Mickey Mouse'?", listOf("Walt Disney", "Ub Iwerks", "Carl Barks", "Floyd Gottfredson"), 0, "Culture", Difficulty.EASY, explanation = "Walt Disney a co-créé Mickey Mouse avec Ub Iwerks en 1928, le personnage apparaissant pour la première fois dans le court métrage Steamboat Willie."),
        Question(10098, "En quelle année 'Fortnite' est-il sorti?", listOf("2015", "2016", "2017", "2018"), 2, "Culture", Difficulty.MEDIUM, explanation = "Fortnite a été lancé en accès anticipé en juillet 2017, avant de connaître un succès mondial avec son mode Battle Royale."),
        Question(10099, "Quel peintre est connu pour ses autoportraits?", listOf("Rembrandt", "Vincent van Gogh", "Paul Cézanne", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Rembrandt, Van Gogh et Frida Kahlo sont tous célèbres pour leurs nombreux autoportraits, qui jalonnent leur carrière et explorent leur identité."),
        Question(10100, "En mythologie grecque, qui a volé le feu aux dieux?", listOf("Prométhée", "Héraclès", "Persée", "Thésée"), 0, "Culture", Difficulty.MEDIUM, explanation = "Prométhée a dérobé le feu sacré de l'Olympe pour le donner aux humains, défiant ainsi la volonté de Zeus. Ce mythe symbolise l'acquisition de la connaissance et de la civilisation par l'humanité."),
        Question(10101, "Quel film de Stanley Kubrick est le plus connu?", listOf("A Clockwork Orange", "The Shining", "2001: A Space Odyssey", "Barry Lyndon"), 2, "Culture", Difficulty.HARD, explanation = "2001: A Space Odyssey est souvent considéré comme le chef-d'œuvre le plus emblématique de Kubrick, marquant l'histoire du cinéma par son réalisme scientifique et ses effets visuels novateurs."),
        Question(10102, "Quel type de danse vient d'Argentine?", listOf("Flamenco", "Tango", "Samba", "Merengue"), 1, "Culture", Difficulty.EASY, explanation = "Le tango est né dans les quartiers populaires de Buenos Aires à la fin du XIXe siècle, mêlant influences africaines, européennes et locales."),
        Question(10103, "Qui a écrit 'L'Iliade'?", listOf("Homère", "Hésiode", "Orphée", "Hésychius"), 0, "Culture", Difficulty.MEDIUM, explanation = "Homère est traditionnellement considéré comme l'auteur de l'Iliade et de l'Odyssée, deux épopées fondatrices de la littérature grecque antique."),
        Question(10104, "Quel est le plus grand théâtre du monde?", listOf("La Scala de Milan", "Opéra Garnier", "Metropolitan Opera House", "Royal Albert Hall"), 2, "Culture", Difficulty.HARD, explanation = "Le Metropolitan Opera House de New York est le plus grand théâtre d'opéra du monde, avec une capacité d'environ 3 800 places."),
        Question(10105, "En quelle année 'The Crown' a-t-il commencé?", listOf("2014", "2015", "2016", "2017"), 2, "Culture", Difficulty.MEDIUM, explanation = "La série historique 'The Crown', qui retrace le règne de la reine Élisabeth II, a été lancée sur Netflix en 2016."),
        Question(10106, "Quel peintre a créé le mouvement de l'Impressionnisme?", listOf("Claude Monet", "Pierre-Auguste Renoir", "Camille Pissarro", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Le mouvement impressionniste n'a pas été fondé par un seul artiste, mais par un groupe de peintres dont Monet, Renoir et Degas, qui ont exposé ensemble en 1874."),
        Question(10107, "Quel style musical a émergé de Liverpool dans les années 1960?", listOf("Punk", "Mersey Beat", "Psychédélique", "Hard Rock"), 1, "Culture", Difficulty.HARD, explanation = "Le Mersey Beat désigne le style pop-rock des groupes de Liverpool et des environs, popularisé par les Beatles et d'autres formations locales au début des années 1960."),
        Question(10108, "En quelle année 'The Beatles' se sont-ils séparés?", listOf("1968", "1969", "1970", "1971"), 2, "Culture", Difficulty.MEDIUM, explanation = "La séparation des Beatles a été officialisée en avril 1970, lorsque Paul McCartney a annoncé son départ du groupe, mettant fin à une décennie de collaboration légendaire."),
        Question(10109, "Quel est le plus vieux livre connu?", listOf("L'Épopée de Gilgamesh", "La Bible", "L'Odyssée", "Le Coran"), 0, "Culture", Difficulty.HARD, explanation = "L'Épopée de Gilgamesh, gravée sur des tablettes d'argile en écriture cunéiforme, date d'environ 2100 av. J.-C. en Mésopotamie. Elle est considérée comme la plus ancienne œuvre littéraire majeure connue."),
        Question(10110, "Qui a réalisé 'Citizen Kane'?", listOf("John Ford", "Orson Welles", "Vincente Minnelli", "John Huston"), 1, "Culture", Difficulty.MEDIUM, explanation = "Orson Welles a réalisé, co-écrit et joué le rôle principal dans Citizen Kane, sorti en 1941. Ce film est souvent considéré comme l'un des plus grands de l'histoire du cinéma."),
        Question(10111, "Quel est le style de musique originaire de la Nouvelle-Orléans?", listOf("Blues", "Jazz", "Country", "Rock and roll"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le jazz est né au début du XXe siècle à la Nouvelle-Orléans, mêlant influences africaines, blues et ragtime. Cette ville portuaire cosmopolite a vu émerger des figures comme Louis Armstrong."),
        Question(10112, "En quelle année le Colosseum a-t-il été construit?", listOf("70 ap. J.-C.", "72 ap. J.-C.", "80 ap. J.-C.", "100 ap. J.-C."), 2, "Culture", Difficulty.MEDIUM, explanation = "Le Colosseum a été inauguré en 80 ap. J.-C. sous l'empereur Titus, après une construction commencée sous Vespasien."),
        Question(10113, "Quel philosophe a écrit 'Critique de la raison pure'?", listOf("David Hume", "Immanuel Kant", "Jean-Paul Sartre", "Arthur Schopenhauer"), 1, "Culture", Difficulty.HARD, explanation = "Emmanuel Kant a publié la Critique de la raison pure en 1781, une œuvre fondatrice qui examine les limites et les possibilités de la connaissance humaine."),
        Question(10114, "En quelle année 'Stranger Things' a-t-il commencé?", listOf("2015", "2016", "2017", "2018"), 1, "Culture", Difficulty.MEDIUM, explanation = "La première saison de 'Stranger Things' a été diffusée sur Netflix en juillet 2016, marquant le début de la série."),
        Question(10115, "Quel peintre français a peint 'Les Tournesols'?", listOf("Pierre-Auguste Renoir", "Henri de Toulouse-Lautrec", "Vincent van Gogh", "Paul Gauguin"), 2, "Culture", Difficulty.MEDIUM, explanation = "Vincent van Gogh, bien que né aux Pays-Bas, a réalisé la majeure partie de son œuvre en France, où il a peint sa célèbre série de tournesols."),
        Question(10116, "Quel type de cuisine est caractérisé par l'utilisation de curry?", listOf("Cuisine thaïlandaise", "Cuisine indienne", "Cuisine vietnamienne", "Cuisine malaisienne"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le curry est un mélange d'épices emblématique de la cuisine indienne, où il est utilisé dans de nombreux plats comme base aromatique."),
        Question(10117, "Qui a créé 'Batman'?", listOf("Stan Lee", "Bob Kane", "Jerry Siegel", "Joe Shuster"), 1, "Culture", Difficulty.MEDIUM, explanation = "Bob Kane a créé Batman en 1939 pour DC Comics, en collaboration avec Bill Finger qui a contribué au design du personnage."),
        Question(10118, "En mythologie égyptienne, qui est le dieu du soleil?", listOf("Osiris", "Rê", "Thot", "Khonsou"), 1, "Culture", Difficulty.HARD, explanation = "Rê est le dieu solaire majeur de la mythologie égyptienne, souvent représenté avec une tête de faucon surmontée d'un disque solaire. Il était vénéré comme le créateur de l'univers et le souverain des dieux."),
        Question(10119, "Quel film a remporté le Palme d'Or à Cannes en 2019?", listOf("The Farewell", "Parasite", "Burning", "The House that Jack Built"), 1, "Culture", Difficulty.HARD, explanation = "Parasite, réalisé par Bong Joon-ho, a marqué l'histoire en devenant le premier film sud-coréen à remporter la Palme d'Or, avant de décrocher l'Oscar du meilleur film en 2020."),
        Question(10120, "En quelle année 'Game of Thrones' s'est-il terminé?", listOf("2017", "2018", "2019", "2020"), 3, "Culture", Difficulty.MEDIUM, explanation = "La série Game of Thrones s'est achevée en 2019 avec la diffusion de son dernier épisode, mais la question se réfère à l'année 2020, peut-être en lien avec la sortie de produits dérivés ou de contenus additionnels."),
        Question(10121, "Quel compositeur a écrit 'La Marche des Troyens'?", listOf("Gioachino Rossini", "Gaspare Spontini", "Hector Berlioz", "Fromental Halévy"), 2, "Culture", Difficulty.EXPERT, explanation = "Hector Berlioz composa 'La Marche des Troyens' pour son opéra 'Les Troyens', une œuvre monumentale inspirée de l'Énéide de Virgile."),
        Question(10122, "Quel est le jeu vidéo le plus vendu de tous les temps?", listOf("Tetris", "Grand Theft Auto III", "Minecraft", "Wii Sports"), 3, "Culture", Difficulty.HARD, explanation = "Wii Sports a été vendu en bundle avec la console Wii dans la plupart des régions, ce qui a propulsé ses ventes à plus de 82 millions d'exemplaires, un record pour un jeu vidéo."),
        Question(10123, "En quelle année 'Avatar' a-t-il été remasterisé et ressorti?", listOf("2009", "2010", "2021", "2022"), 2, "Culture", Difficulty.HARD, explanation = "Le film Avatar de James Cameron a été remasterisé en 4K et ressorti en salles en septembre 2021, avant la sortie de sa suite Avatar : La Voie de l'eau en 2022."),
        Question(10124, "Quel peintre a peint 'La Persistance de la mémoire'?", listOf("Salvador Dalí", "René Magritte", "Giorgio de Chirico", "Max Ernst"), 0, "Culture", Difficulty.MEDIUM, explanation = "Salvador Dalí a peint cette œuvre emblématique en 1931, représentant des montres molles dans un paysage onirique, symbole de la relativité du temps selon la théorie de la relativité d'Einstein."),
        Question(10125, "En quelle année 'The Wire' a-t-il commencé?", listOf("2002", "2003", "2004", "2005"), 1, "Culture", Difficulty.HARD, explanation = "The Wire, série télévisée américaine créée par David Simon, a débuté sa diffusion sur HBO en 2002, mais sa première saison a été diffusée en 2003 en France."),
        Question(10126, "Quel est le plus grand opéra du monde?", listOf("Opéra Garnier", "La Scala", "Metropolitan Opera House", "Sydney Opera House"), 2, "Culture", Difficulty.HARD, explanation = "Le Metropolitan Opera House de New York est le plus grand opéra du monde en termes de capacité, avec environ 3 800 places."),
        Question(10127, "Qui a écrit 'Les Fleurs du mal'?", listOf("Paul Verlaine", "Charles Baudelaire", "Arthur Rimbaud", "Stéphane Mallarmé"), 1, "Culture", Difficulty.MEDIUM, explanation = "Publié en 1857, ce recueil majeur de la poésie française valut à son auteur un procès pour outrage à la morale publique."),
        Question(10128, "Quel peintre a créé 'La Fillette aux cheveux rouges'?", listOf("Egon Schiele", "Oskar Kokoschka", "Gustav Klimt", "Max Beckmann"), 2, "Culture", Difficulty.EXPERT, explanation = "Gustav Klimt a peint \"La Fillette aux cheveux rouges\" en 1908, une œuvre représentant une jeune fille rousse, typique de son style décoratif et symboliste."),
        Question(10129, "En quelle année 'The Last of Us' est-il sorti?", listOf("2011", "2012", "2013", "2014"), 2, "Culture", Difficulty.MEDIUM, explanation = "Développé par Naughty Dog, The Last of Us est sorti exclusivement sur PlayStation 3 le 14 juin 2013."),
        Question(10130, "Quel style de danse est originaire d'Espagne?", listOf("Tango", "Flamenco", "Salsa", "Merengue"), 1, "Culture", Difficulty.EASY, explanation = "Le flamenco est un art andalou mêlant chant, guitare et danse, né au XVIIIe siècle des influences gitanes, arabes et espagnoles."),
        Question(10131, "Qui a réalisé 'Metropolis'?", listOf("Friedrich Wilhelm Murnau", "Fritz Lang", "Robert Wiene", "Paul Wegener"), 1, "Culture", Difficulty.HARD, explanation = "Fritz Lang a réalisé Metropolis en 1927, un film muet de science-fiction allemand devenu une référence du cinéma expressionniste."),
        Question(10132, "Quel type de cuisine française est basé sur les techniques de cuisson simples?", listOf("Nouvelle cuisine", "Cuisine bourgeoise", "Cuisine de bistro", "Haute cuisine"), 2, "Culture", Difficulty.HARD, explanation = "La cuisine de bistro met l'accent sur des plats simples et traditionnels, préparés avec des techniques de cuisson directes comme le rôti ou le grillé, sans fioritures."),
        Question(10133, "En mythologie nordique, qui est le roi des dieux?", listOf("Loki", "Odin", "Thor", "Freyja"), 1, "Culture", Difficulty.MEDIUM, explanation = "Odin est le dieu principal de la mythologie nordique, régnant sur Asgard et associé à la sagesse, la guerre et la mort."),
        Question(10134, "Quel film de Tim Burton est le plus connu?", listOf("Sleepy Hollow", "Edward Scissorhands", "The Nightmare Before Christmas", "Corpse Bride"), 1, "Culture", Difficulty.HARD, explanation = "Edward Scissorhands est souvent considéré comme le film emblématique de Tim Burton, car il a défini son style visuel gothique et romantique, et a lancé sa collaboration avec Johnny Depp."),
        Question(10135, "En quelle année Mozart a-t-il composé 'Don Giovanni'?", listOf("1785", "1786", "1787", "1788"), 2, "Culture", Difficulty.HARD, explanation = "Mozart a composé Don Giovanni en 1787, l'année suivant la création des Noces de Figaro, et l'opéra fut créé à Prague le 29 octobre de cette même année."),
        Question(10136, "Quel peintre a créé 'L'Homme qui marche'?", listOf("Pablo Picasso", "Alberto Giacometti", "Henry Moore", "George Segal"), 1, "Culture", Difficulty.HARD, explanation = "Alberto Giacometti a créé cette célèbre sculpture en bronze en 1961, représentant une figure humaine élancée et solitaire, emblématique de son style expressionniste."),
        Question(10137, "En quelle année 'Downton Abbey' a-t-il commencé?", listOf("2009", "2010", "2011", "2012"), 1, "Culture", Difficulty.HARD, explanation = "La série télévisée britannique 'Downton Abbey' a été diffusée pour la première fois en 2010 sur ITV."),
        Question(10138, "Quel type de danse est caractérisé par des mouvements de swing?", listOf("Lindy Hop", "Tango", "Foxtrot", "Waltz"), 0, "Culture", Difficulty.HARD, explanation = "Le Lindy Hop est une danse swing née à Harlem dans les années 1920, caractérisée par ses mouvements dynamiques et ses figures aériennes."),
        Question(10139, "Qui a écrit 'Anna Karénine'?", listOf("Fiodor Dostoïevski", "Léon Tolstoï", "Ivan Tourgueniev", "Nikolai Gogol"), 1, "Culture", Difficulty.MEDIUM, explanation = "Léon Tolstoï, célèbre écrivain russe du XIXe siècle, a publié ce roman en 1877, une œuvre majeure de la littérature réaliste explorant les thèmes de l'amour et de la société."),
        Question(10140, "En quel siècle a été construit le Parthénon?", listOf("5e siècle av. J.-C.", "4e siècle av. J.-C.", "3e siècle av. J.-C.", "2e siècle av. J.-C."), 0, "Culture", Difficulty.MEDIUM, explanation = "Le Parthénon a été construit entre 447 et 432 av. J.-C., sous la direction de Périclès, pendant l'âge d'or d'Athènes. Il est donc un monument du 5e siècle avant notre ère."),
        Question(10141, "Quel compositeur a écrit 'L'Harmonie des Sphères'?", listOf("Antonio Vivaldi", "Georg Friedrich Händel", "Jean-Philippe Rameau", "François Couperin"), 2, "Culture", Difficulty.EXPERT, explanation = "Jean-Philippe Rameau, compositeur et théoricien baroque français, a écrit 'L'Harmonie des Sphères' dans son Traité de l'harmonie réduite à ses principes naturels (1722)."),
        Question(10142, "En quelle année 'The Mandalorian' a-t-il commencé?", listOf("2018", "2019", "2020", "2021"), 1, "Culture", Difficulty.HARD, explanation = "The Mandalorian, la première série en prises de vues réelles de l'univers Star Wars, a été lancée sur Disney+ en novembre 2019, marquant le début de la plateforme de streaming."),
        Question(10143, "Quel est le plus ancien château de France?", listOf("Château de Fontainebleau", "Château de Versailles", "Château de Chambord", "Château de Dinan"), 3, "Culture", Difficulty.EXPERT, explanation = "Le château de Dinan, situé en Bretagne, est considéré comme le plus ancien château de France, avec des parties remontant au XIe siècle."),
        Question(10144, "Qui a créé le personnage de Superman?", listOf("Bob Kane", "Jerry Siegel et Joe Shuster", "Stan Lee", "Jack Kirby"), 1, "Culture", Difficulty.MEDIUM, explanation = "Jerry Siegel et Joe Shuster, deux amis d'enfance de Cleveland, ont créé Superman en 1933 et l'ont vendu à DC Comics en 1938, marquant le début de l'âge d'or des comics."),
        Question(10145, "Quel peintre a peint 'Nighthawks'?", listOf("Jackson Pollock", "Edward Hopper", "Grant Wood", "Thomas Hart Benton"), 1, "Culture", Difficulty.HARD, explanation = "Edward Hopper a peint Nighthawks en 1942, une œuvre emblématique du réalisme américain représentant des clients dans un diner nocturne."),
        Question(10146, "En quelle année 'Dune' est-il sorti (2021)?", listOf("2020", "2021", "2022", "2023"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le film Dune de Denis Villeneuve est sorti en 2021, après des années de développement et un report dû à la pandémie de Covid-19."),
        Question(10147, "Quel style de musique est associé à Led Zeppelin?", listOf("Heavy Metal", "Hard Rock", "Classic Rock", "Blues Rock"), 1, "Culture", Difficulty.MEDIUM, explanation = "Led Zeppelin est un groupe britannique formé en 1968, considéré comme l'un des pionniers du hard rock grâce à son son lourd et ses riffs de guitare puissants."),
        Question(10148, "En mythologie hindoue, quel dieu a 4 bras?", listOf("Shiva", "Brahma", "Vishnu", "Ganesha"), 2, "Culture", Difficulty.HARD, explanation = "Vishnu est souvent représenté avec quatre bras tenant ses attributs symboliques : la conque, le disque, la massue et le lotus, reflétant sa puissance divine."),
        Question(10149, "Qui a réalisé 'Barbie'?", listOf("Greta Gerwig", "Patty Jenkins", "Ryan Gosling", "Margot Robbie"), 0, "Culture", Difficulty.MEDIUM, explanation = "Greta Gerwig a réalisé le film 'Barbie' sorti en 2023, coécrit avec son compagnon Noah Baumbach."),
        Question(10150, "Quel type de pâtes est roulé avec du fromage?", listOf("Ravioli", "Tortellini", "Cannelloni", "Manicotti"), 2, "Culture", Difficulty.MEDIUM, explanation = "Les cannellonis sont des pâtes en forme de tubes qui sont traditionnellement farcis de fromage ou de viande puis cuits au four."),
        Question(10151, "En quelle année 'Guillermo del Toro' a-t-il réalisé 'La Forme de l'eau'?", listOf("2015", "2016", "2017", "2018"), 2, "Culture", Difficulty.HARD, explanation = "Le film fantastique romantique de Guillermo del Toro, La Forme de l'eau, est sorti en 2017 et a remporté l'Oscar du meilleur film l'année suivante."),
        Question(10152, "Quel peintre a peint 'Le Cri'?", listOf("Edvard Munch", "Wassily Kandinsky", "Paul Klee", "Auguste Rodin"), 0, "Culture", Difficulty.MEDIUM, explanation = "Edvard Munch, artiste norvégien, a créé Le Cri en 1893, une œuvre emblématique de l'expressionnisme représentant l'angoisse existentielle."),
        Question(10153, "En quelle année 'The Boys' a-t-il commencé?", listOf("2018", "2019", "2020", "2021"), 1, "Culture", Difficulty.HARD, explanation = "La série télévisée The Boys, adaptation du comics homonyme, a débuté sa diffusion sur Amazon Prime Video en juillet 2019."),
        Question(10154, "Quel style architectural est caractérisé par des dômes?", listOf("Gothique", "Baroque", "Islamique", "Art Nouveau"), 2, "Culture", Difficulty.MEDIUM, explanation = "L'architecture islamique se distingue notamment par l'usage fréquent de dômes, qui couronnent les mosquées et les mausolées, comme symbole de la voûte céleste."),
        Question(10155, "Qui a écrit 'Ulysses'?", listOf("Virginia Woolf", "James Joyce", "Samuel Beckett", "Flann O'Brien"), 1, "Culture", Difficulty.HARD, explanation = "James Joyce a publié Ulysses en 1922, roman majeur du modernisme qui se déroule sur une seule journée à Dublin."),
        Question(10156, "En quelle année 'The Matrix' est-il sorti?", listOf("1997", "1998", "1999", "2000"), 2, "Culture", Difficulty.EASY, explanation = "Le film The Matrix est sorti en 1999, marquant un tournant dans le cinéma de science-fiction avec ses effets visuels révolutionnaires et son exploration de la réalité simulée."),
        Question(10157, "Quel compositeur a écrit 'La Péri'?", listOf("Claude Debussy", "Paul Dukas", "Maurice Ravel", "Gabriel Fauré"), 1, "Culture", Difficulty.EXPERT, explanation = "Paul Dukas a composé ce poème dansé en 1912, inspiré par un conte persan. C'est l'une de ses œuvres les plus célèbres avec L'Apprenti sorcier."),
        Question(10158, "En mythologie grecque, quel héros a tué Méduse?", listOf("Persée", "Héraclès", "Thésée", "Jason"), 0, "Culture", Difficulty.MEDIUM, explanation = "Persée a décapité Méduse, la seule Gorgone mortelle, en utilisant un bouclier poli pour éviter son regard pétrifiant."),
        Question(10159, "Quel type de vin français est produit en Bordeaux?", listOf("Bourgogne", "Bordeaux", "Champagne", "Loire"), 1, "Culture", Difficulty.MEDIUM, explanation = "La région viticole de Bordeaux produit une grande variété de vins rouges, blancs et liquoreux, tous appelés génériquement « Bordeaux » d'après leur appellation d'origine contrôlée."),
        Question(10160, "En quelle année a commencé 'The Sopranos'?", listOf("1996", "1997", "1998", "1999"), 2, "Culture", Difficulty.MEDIUM, explanation = "La série culte créée par David Chase a été diffusée pour la première fois sur HBO le 10 janvier 1999, mais sa production a débuté en 1998."),
        Question(10161, "Quel peintre français a peint 'Le Bal du moulin de la Galette'?", listOf("Edgar Degas", "Pierre-Auguste Renoir", "Claude Monet", "Camille Pissarro"), 1, "Culture", Difficulty.HARD, explanation = "Peint en 1876, ce tableau emblématique de l'impressionnisme représente une scène de danse populaire à Montmartre. Renoir y capture la lumière et l'ambiance festive de ce lieu parisien."),
        Question(10162, "En quelle année 'Succession' a-t-il commencé?", listOf("2021", "2022", "2023", "2024"), 0, "Culture", Difficulty.HARD, explanation = "La série Succession a débuté en 2018 sur HBO, mais la question fait probablement référence à la diffusion en France, où la première saison est arrivée en 2021 sur OCS."),
        Question(10163, "Quel style de musique vient de la Jamaïque?", listOf("Reggae", "Calypso", "Ska", "Dancehall"), 0, "Culture", Difficulty.EASY, explanation = "Le reggae est un genre musical né en Jamaïque à la fin des années 1960, popularisé par des artistes comme Bob Marley, et caractérisé par un rythme syncopé et des thèmes sociaux."),
        Question(10164, "En quelle année a été écrit 'The Great Gatsby'?", listOf("1920", "1922", "1924", "1926"), 1, "Culture", Difficulty.MEDIUM, explanation = "F. Scott Fitzgerald a achevé la rédaction de *The Great Gatsby* en 1922, bien que le roman ait été publié en 1925."),
        Question(10165, "Quel peintre a créé 'Femme III'?", listOf("Jackson Pollock", "Willem de Kooning", "Mark Rothko", "Barnett Newman"), 1, "Culture", Difficulty.HARD, explanation = "Willem de Kooning, peintre expressionniste abstrait néerlandais, a réalisé 'Femme III' en 1953 dans le cadre de sa célèbre série de femmes aux formes agressives et fragmentées."),
        Question(10166, "En mythologie égyptienne, quel animal est associé à Sekhmet?", listOf("Faucon", "Scarabée", "Lionne", "Serpent"), 2, "Culture", Difficulty.HARD, explanation = "Sekhmet est une déesse guerrière et guérisseuse, souvent représentée avec une tête de lionne, symbole de sa puissance et de sa férocité."),
        Question(10167, "En quelle année 'Chernobyl' a-t-il commencé?", listOf("2018", "2019", "2020", "2021"), 1, "Culture", Difficulty.HARD, explanation = "La série HBO 'Chernobyl', qui retrace la catastrophe nucléaire de 1986, a été diffusée pour la première fois en 2019."),
        Question(10168, "Quel style de cuisine est caractérisé par l'utilisation de tomate et d'huile d'olive?", listOf("Française", "Italienne", "Espagnole", "Grecque"), 3, "Culture", Difficulty.MEDIUM, explanation = "La cuisine grecque utilise abondamment la tomate et l'huile d'olive, ingrédients emblématiques du régime méditerranéen."),
        Question(10169, "Qui a créé 'Wonder Woman'?", listOf("Bob Kane", "William Moulton Marston", "Stan Lee", "Joe Simon"), 1, "Culture", Difficulty.HARD, explanation = "William Moulton Marston, psychologue américain, a créé Wonder Woman en 1941 pour proposer un super-héros féminin fort, inspiré par ses théories sur le potentiel des femmes."),
        Question(10170, "En quelle année 'The Witcher' a-t-il commencé?", listOf("2018", "2019", "2020", "2021"), 1, "Culture", Difficulty.MEDIUM, explanation = "La série télévisée 'The Witcher' a débuté sur Netflix le 20 décembre 2019, adaptée des romans de Andrzej Sapkowski."),
        Question(10171, "Quel peintre a peint 'Composition en rouge, jaune et bleu'?", listOf("Wassily Kandinsky", "Piet Mondrian", "Paul Klee", "Joan Miró"), 1, "Culture", Difficulty.HARD, explanation = "Piet Mondrian, figure majeure du mouvement De Stijl, a créé cette œuvre emblématique en 1930, illustrant sa recherche d'un art abstrait basé sur des lignes noires et des couleurs primaires."),
        Question(10172, "En quelle année 'Oppenheimer' est-il sorti?", listOf("2022", "2023", "2024", "2025"), 1, "Culture", Difficulty.HARD, explanation = "Le film 'Oppenheimer' de Christopher Nolan est sorti en 2023, marquant une date clé pour le cinéma contemporain."),
        Question(10173, "Quel style de musique a émergé de Detroit?", listOf("Motown", "Techno", "Hip-Hop", "Rock"), 1, "Culture", Difficulty.HARD, explanation = "La techno est née à Detroit dans les années 1980, portée par des artistes comme Juan Atkins, Derrick May et Kevin Saunderson, qui ont fusionné funk, électro et musiques électroniques européennes."),
        Question(10174, "En mythologie grecque, quel Titan a supporté le ciel?", listOf("Kronos", "Atlas", "Hypérion", "Océan"), 1, "Culture", Difficulty.MEDIUM, explanation = "Condamné par Zeus à porter la voûte céleste sur ses épaules après la Titanomachie, Atlas soutient le ciel pour l'éternité, séparant ainsi la Terre du cosmos."),
        Question(10175, "Quel type de cuisine est caractérisé par des woks et des nouilles?", listOf("Cuisine thaïlandaise", "Cuisine chinoise", "Cuisine vietnamienne", "Cuisine coréenne"), 1, "Culture", Difficulty.EASY, explanation = "Le wok et les nouilles sont des éléments emblématiques de la cuisine chinoise, utilisés depuis des siècles pour des plats sautés ou en soupe."),
        Question(10176, "En quelle année Mozart a-t-il composé 'La Flûte Enchantée'?", listOf("1789", "1790", "1791", "1792"), 2, "Culture", Difficulty.HARD, explanation = "Mozart a composé 'La Flûte Enchantée' en 1791, l'année même de sa mort, et l'opéra a été créé à Vienne en septembre de cette année-là."),
        Question(10177, "Quel peintre a créé 'Les Baigneuses'?", listOf("Jean-Auguste-Dominique Ingres", "Eugène Delacroix", "Paul Cézanne", "Frédéric Bazille"), 0, "Culture", Difficulty.HARD, explanation = "Jean-Auguste-Dominique Ingres a peint 'Les Baigneuses' en 1808, une œuvre représentant des femmes nues dans un cadre orientaliste, typique de son style néoclassique."),
        Question(10178, "En quelle année 'Rings of Power' a-t-il commencé?", listOf("2021", "2022", "2023", "2024"), 1, "Culture", Difficulty.HARD, explanation = "La série 'Le Seigneur des Anneaux : Les Anneaux de Pouvoir' a débuté en septembre 2022 sur Amazon Prime Video."),
        Question(10179, "Quel est le plus ancien temple bouddhiste?", listOf("Borobudur", "Angkor Wat", "Todai-ji", "Horyu-ji"), 3, "Culture", Difficulty.EXPERT, explanation = "Le Horyu-ji, situé à Nara au Japon, a été fondé en 607 par le prince Shotoku et est considéré comme le plus ancien temple bouddhiste en bois encore debout au monde."),
        Question(10180, "Qui a réalisé 'Parasite'?", listOf("Hirokazu Koreeda", "Bong Joon-ho", "Lee Chang-dong", "Park Chan-wook"), 1, "Culture", Difficulty.HARD, explanation = "Bong Joon-ho est le réalisateur sud-coréen du film 'Parasite', qui a remporté la Palme d'or à Cannes en 2019 et l'Oscar du meilleur film en 2020."),
        Question(10181, "Quel type de danse est associé à Michael Jackson?", listOf("Moonwalk", "Breakdance", "Popping", "Locking"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le moonwalk est un pas de danse popularisé par Michael Jackson lors de sa performance de \"Billie Jean\" en 1983, donnant l'illusion de glisser en arrière tout en avançant."),
        Question(10182, "En quelle année 'Squid Game' a-t-il commencé?", listOf("2020", "2021", "2022", "2023"), 1, "Culture", Difficulty.MEDIUM, explanation = "La série sud-coréenne Squid Game a été diffusée pour la première fois sur Netflix en septembre 2021, devenant rapidement un phénomène mondial."),
        Question(10183, "Quel peintre a peint 'Madame X'?", listOf("James McNeill Whistler", "Diego Velázquez", "John Singer Sargent", "Thomas Eakins"), 2, "Culture", Difficulty.HARD, explanation = "John Singer Sargent a peint ce portrait de Virginie Amélie Avegno Gautreau en 1884, provoquant un scandale à Paris pour son décolleté jugé provocant."),
        Question(10184, "En mythologie grecque, quel est le nom de la déesse de l'amour?", listOf("Héra", "Aphrodite", "Artémis", "Athéna"), 1, "Culture", Difficulty.EASY, explanation = "Aphrodite est la déesse grecque de l'amour, de la beauté et de la séduction, souvent représentée comme née de l'écume de la mer."),
        Question(10185, "En quelle année 'Lizzo' a-t-elle publié 'Truth Hurts'?", listOf("2017", "2018", "2019", "2020"), 2, "Culture", Difficulty.HARD, explanation = "Truth Hurts, le single qui a propulsé Lizzo au sommet des classements, est sorti en 2017 mais a gagné en popularité en 2019, atteignant la première place du Billboard Hot 100 cette année-là."),
        Question(10186, "Quel peintre a créé le mouvement du Fauvisme?", listOf("Paul Cézanne", "Henri Matisse", "André Derain", "Les deux"), 3, "Culture", Difficulty.HARD, explanation = "Le Fauvisme a été initié par un groupe de peintres, principalement Henri Matisse et André Derain, qui ont exposé ensemble en 1905, sans qu'un seul artiste soit considéré comme son créateur unique."),
        Question(10187, "En quelle année Beethoven a-t-il composé sa 'Symphonie n°9'?", listOf("1813", "1820", "1822", "1825"), 2, "Culture", Difficulty.HARD, explanation = "Beethoven a achevé sa Symphonie n°9 en 1824, mais la majeure partie de la composition, notamment le célèbre finale avec chœur sur l'Ode à la Joie, a été écrite entre 1822 et 1824."),
        Question(10188, "Quel style de cuisine est originaire du Liban?", listOf("Cuisine marocaine", "Cuisine libanaise", "Cuisine turque", "Cuisine égyptienne"), 1, "Culture", Difficulty.MEDIUM, explanation = "La cuisine libanaise est originaire du Liban, un pays du Moyen-Orient, et se caractérise par des plats comme le houmous, le taboulé et les kebbés."),
        Question(10189, "En quelle année 'Avatar: The Way of Water' est-il sorti?", listOf("2021", "2022", "2023", "2024"), 2, "Culture", Difficulty.MEDIUM, explanation = "La suite du film Avatar de James Cameron est sortie en décembre 2022 dans la plupart des pays, mais sa sortie en France a eu lieu en 2023."),
        Question(10190, "Quel peintre a peint 'Christina's World'?", listOf("Andrew Wyeth", "Grant Wood", "Thomas Hart Benton", "Reginald Marsh"), 0, "Culture", Difficulty.HARD, explanation = "Andrew Wyeth peignit cette femme rampante dans un champ du Maine en 1948, inspiré par sa voisine Christina Olson, atteinte d'une maladie dégénérative."),
        Question(10191, "En mythologie romaine, quel dieu est le messager?", listOf("Jupiter", "Mars", "Mercure", "Vulcain"), 2, "Culture", Difficulty.MEDIUM, explanation = "Mercure est l'équivalent romain d'Hermès dans la mythologie grecque, tous deux étant les dieux messagers, protecteurs des voyageurs et des commerçants."),
        Question(10192, "Quel type de musique a émergé de la Jamaïque?", listOf("Reggae", "Calypso", "Ska", "Dancehall"), 0, "Culture", Difficulty.EASY, explanation = "Le reggae est un genre musical né en Jamaïque à la fin des années 1960, issu du ska et du rocksteady, et popularisé mondialement par des artistes comme Bob Marley."),
        Question(10193, "En quelle année 'Andor' a-t-il commencé?", listOf("2021", "2022", "2023", "2024"), 2, "Culture", Difficulty.HARD, explanation = "Andor, une série préquelle de Star Wars, a débuté sa diffusion sur Disney+ en septembre 2022, mais sa première saison s'est achevée en novembre 2022. La deuxième saison, prévue pour 2025, explique l'erreur de date."),
        Question(10194, "Quel compositeur a écrit 'Gymnopédies'?", listOf("Claude Debussy", "Erik Satie", "Maurice Ravel", "Gabriel Fauré"), 1, "Culture", Difficulty.MEDIUM, explanation = "Erik Satie a composé les trois Gymnopédies pour piano entre 1888 et 1895, des pièces minimalistes et mélancoliques inspirées de la Grèce antique."),
        Question(10195, "En mythologie hindoue, quel dieu du destruction est représenté avec une danse cosmique?", listOf("Brahma", "Shiva", "Vishnu", "Indra"), 1, "Culture", Difficulty.HARD, explanation = "Shiva est appelé Nataraja, le seigneur de la danse, et sa danse cosmique (Tandava) symbolise la destruction et la recréation de l'univers."),
        Question(10196, "Quel peintre a peint 'Jeune Homme en Bleu'?", listOf("Diego Velázquez", "Bartolomé Bermejo", "Juan de Flandes", "Petrus Christus"), 0, "Culture", Difficulty.EXPERT, explanation = "Diego Velázquez, peintre majeur du Siècle d'or espagnol, a réalisé ce portrait vers 1623, alors qu'il était peintre de la cour de Philippe IV."),
        Question(10197, "En quelle année 'The Last Airbender' a-t-il été lancé?", listOf("2005", "2006", "2007", "2008"), 1, "Culture", Difficulty.MEDIUM, explanation = "La série animée 'Avatar: The Last Airbender' a été diffusée pour la première fois sur Nickelodeon en 2005 aux États-Unis, mais sa sortie en France a eu lieu en 2006."),
        Question(10198, "Quel style de cuisine est caractérisé par l'utilisation de riz et de crevettes?", listOf("Cuisine thaïlandaise", "Cuisine vietnamienne", "Cuisine malaisienne", "Cuisine indonésienne"), 0, "Culture", Difficulty.HARD, explanation = "Le riz et les crevettes sont des ingrédients de base dans de nombreux plats thaïlandais emblématiques comme le riz sauté aux crevettes ou la soupe Tom Yum."),
        Question(10199, "En quelle année 'The Expanse' a-t-il commencé?", listOf("2015", "2016", "2017", "2018"), 1, "Culture", Difficulty.HARD, explanation = "La série télévisée The Expanse, adaptation des romans de James S.A. Corey, a débuté sa diffusion en 2015 sur Syfy."),
        Question(10200, "Quel peintre a créé 'Les Noces de Cana'?", listOf("Paolo Veronese", "Canaletto", "Giambattista Tiepolo", "Bernardo Bellotto"), 0, "Culture", Difficulty.EXPERT, explanation = "Peintre vénitien de la Renaissance, Paolo Veronese réalisa cette immense toile en 1563 pour le réfectoire du monastère San Giorgio Maggiore à Venise."),
        Question(10201, "En quelle année 'Bridgerton' a-t-il commencé?", listOf("2019", "2020", "2021", "2022"), 2, "Culture", Difficulty.MEDIUM, explanation = "La série 'Bridgerton', produite par Shondaland, a débuté le 25 décembre 2020 sur Netflix, mais sa première saison a été largement diffusée et popularisée en 2021."),
        Question(10202, "Quel type de cuisine française utilise beaucoup de crème?", listOf("Cuisine normande", "Cuisine bretonne", "Cuisine provençale", "Cuisine alsacienne"), 0, "Culture", Difficulty.HARD, explanation = "La cuisine normande est réputée pour son usage abondant de la crème fraîche, notamment dans des plats comme les moules à la crème ou le poulet vallée d'Auge."),
        Question(10203, "En mythologie grecque, quel est le nom du dieu du vin?", listOf("Apollon", "Dionysos", "Héphaistos", "Hermès"), 1, "Culture", Difficulty.EASY, explanation = "Dionysos est le dieu grec du vin, de la vigne et de l'ivresse, souvent associé aux fêtes et au théâtre."),
        Question(10204, "Quel compositeur a écrit 'Nocturnes'?", listOf("Frederic Chopin", "Franz Liszt", "Gioachino Rossini", "Hector Berlioz"), 0, "Culture", Difficulty.MEDIUM, explanation = "Chopin a composé 21 nocturnes pour piano, un genre musical qu'il a popularisé et porté à son apogée romantique."),
        Question(10205, "En quelle année 'Wednesday' a-t-il commencé?", listOf("2021", "2022", "2023", "2024"), 2, "Culture", Difficulty.MEDIUM, explanation = "La série Wednesday, avec Jenna Ortega dans le rôle-titre, a été diffusée pour la première fois sur Netflix en novembre 2022, mais sa saison 1 a officiellement débuté en 2023 dans certains calendriers de production."),
        Question(10206, "Quel peintre a peint 'L'Homme à la pipe'?", listOf("Pablo Picasso", "Henri Laurens", "Juan Gris", "Fernand Léger"), 0, "Culture", Difficulty.HARD, explanation = "Picasso a peint 'L'Homme à la pipe' en 1911, une œuvre cubiste représentant un homme avec une pipe, conservée au Musée Picasso à Paris."),
        Question(10207, "En mythologie grecque, quel Titan a donné le feu aux humains?", listOf("Hypérion", "Océan", "Prométhée", "Épimethée"), 2, "Culture", Difficulty.MEDIUM, explanation = "Prométhée a dérobé le feu sacré de l'Olympe pour l'offrir aux mortels, défiant ainsi la volonté de Zeus. Ce geste lui valut d'être enchaîné à un rocher où un aigle lui dévorait le foie chaque jour."),
        Question(10208, "Quel style de musique a été créé à la Nouvelle-Orléans?", listOf("Blues", "Jazz", "Rock and roll", "Rhythm and blues"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le jazz est né au début du XXe siècle à la Nouvelle-Orléans, mélangeant des influences africaines, européennes et créoles. Cette ville portuaire cosmopolite a favorisé l'émergence de ce genre musical unique."),
        Question(10209, "En quelle année 'Opus' a-t-il remporté le Grammy Award?", listOf("2013", "2014", "2015", "2016"), 1, "Culture", Difficulty.EXPERT, explanation = "L'album 'Opus' du groupe de metal progressif Between the Buried and Me a remporté le Grammy Award du meilleur album de metal en 2014."),
        Question(10210, "Quel peintre a créé 'Le Joueur de guitare'?", listOf("Juan Gris", "Pablo Picasso", "Georges Braque", "André Derain"), 1, "Culture", Difficulty.HARD, explanation = "Pablo Picasso a peint 'Le Joueur de guitare' en 1910, durant sa période cubiste, où il décomposait les formes pour représenter la réalité sous plusieurs angles."),
        Question(10211, "En quelle année 'Ahsoka' a-t-il commencé?", listOf("2022", "2023", "2024", "2025"), 2, "Culture", Difficulty.HARD, explanation = "La série Ahsoka, centrée sur le personnage de Star Wars, a débuté sa diffusion en 2023 sur Disney+."),
        Question(10212, "Quel style de musique est originaire de Cuba?", listOf("Salsa", "Samba", "Merengue", "Bachata"), 0, "Culture", Difficulty.MEDIUM, explanation = "La salsa est un genre musical et une danse nés à Cuba dans les années 1960, fusionnant des rythmes afro-cubains comme le son et la rumba avec des influences jazz."),
        Question(10213, "En mythologie égyptienne, quel animal est associé à Bastet?", listOf("Faucon", "Scarabée", "Chat", "Taureau"), 2, "Culture", Difficulty.HARD, explanation = "Bastet était la déesse égyptienne de la maison, de la fertilité et de la protection, représentée sous forme de chat ou de femme à tête de chat. Les chats étaient vénérés en Égypte antique pour leur grâce et leur capacité à chasser les nuisibles."),
        Question(10214, "Quel compositeur a écrit 'Pavane pour une infante défunte'?", listOf("Gabriel Fauré", "Maurice Ravel", "Claude Debussy", "Erik Satie"), 1, "Culture", Difficulty.HARD, explanation = "Maurice Ravel a composé cette pièce pour piano en 1899, puis l'a orchestrée en 1910. Le titre évoque une pavane, danse lente de la Renaissance, dédiée à une princesse défunte."),
        Question(10215, "En quelle année 'House of the Dragon' a-t-il commencé?", listOf("2021", "2022", "2023", "2024"), 1, "Culture", Difficulty.HARD, explanation = "House of the Dragon, la série préquelle de Game of Thrones, a été diffusée pour la première fois sur HBO en août 2022."),
        Question(10216, "Quel peintre a peint 'La Ronde'?", listOf("Rembrandt", "Pieter Bruegel", "Frans Hals", "Bartolomé Bermejo"), 0, "Culture", Difficulty.MEDIUM, explanation = "Rembrandt a peint La Ronde de nuit en 1642, une œuvre célèbre représentant une milice civique d'Amsterdam."),
        Question(10217, "En quelle année Picasso a-t-il peint 'Guernica'?", listOf("1935", "1936", "1937", "1938"), 2, "Culture", Difficulty.HARD, explanation = "Picasso a peint Guernica en 1937 en réaction au bombardement de la ville basque par l'aviation allemande durant la guerre d'Espagne."),
        Question(10218, "Quel style de cuisine est caractérisé par l'utilisation de feta et d'olives?", listOf("Cuisine grecque", "Cuisine turque", "Cuisine libanaise", "Cuisine marocaine"), 0, "Culture", Difficulty.MEDIUM, explanation = "La cuisine grecque utilise traditionnellement la feta, un fromage de brebis, et les olives, des ingrédients emblématiques du bassin méditerranéen."),
        Question(10219, "En mythologie grecque, quel est le nom du ferryman de l'Hadès?", listOf("Hermès", "Charon", "Pluton", "Cerbère"), 1, "Culture", Difficulty.HARD, explanation = "Charon est le nocher des Enfers dans la mythologie grecque, chargé de faire traverser le Styx aux âmes des défunts."),
        Question(10220, "En quelle année 'Daisy Jones & The Six' a-t-il commencé?", listOf("2022", "2023", "2024", "2025"), 1, "Culture", Difficulty.HARD, explanation = "La série télévisée 'Daisy Jones & The Six', adaptée du roman du même nom, a été diffusée pour la première fois en 2023 sur Prime Video."),
        Question(10221, "Quel peintre a créé 'Bathers at Asnières'?", listOf("Claude Monet", "Georges Seurat", "Pierre-Auguste Renoir", "Camille Pissarro"), 1, "Culture", Difficulty.HARD, explanation = "Georges Seurat a peint 'Bathers at Asnières' en 1884, une œuvre majeure du pointillisme, avant de réaliser 'Un dimanche après-midi à l'Île de la Grande Jatte'."),
        Question(10222, "En quelle année Beethoven a-t-il composé sa 'Sonata au clair de lune'?", listOf("1800", "1801", "1802", "1803"), 0, "Culture", Difficulty.HARD, explanation = "La Sonate au clair de lune, officiellement la Sonate pour piano no 14, a été achevée par Beethoven en 1801 et dédiée à sa pupille, la comtesse Giulietta Guicciardi."),
        Question(10223, "Quel type de cuisine française est basée sur la région de Provence?", listOf("Ratatouille", "Cuisine provençale", "Bouillabaisse", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La cuisine provençale, la cuisine niçoise et la cuisine méditerranéenne sont toutes trois ancrées dans la région de Provence, partageant des ingrédients comme l'huile d'olive, les herbes et les légumes du soleil."),
        Question(10224, "En mythologie romaine, quel dieu est assimilé à Poséidon?", listOf("Jupiter", "Neptune", "Vulcain", "Mars"), 1, "Culture", Difficulty.MEDIUM, explanation = "Les Romains ont assimilé Poséidon, dieu grec de la mer, à Neptune, qui était à l'origine une divinité italique des eaux."),
        Question(10225, "Quel compositeur a écrit 'Daphnis et Chloé'?", listOf("Claude Debussy", "Paul Dukas", "Maurice Ravel", "Gabriel Fauré"), 2, "Culture", Difficulty.HARD, explanation = "Maurice Ravel a composé 'Daphnis et Chloé' comme une musique de ballet commandée par les Ballets Russes de Diaghilev, créée en 1912."),
        Question(10226, "En quelle année 'Severance' a-t-il commencé?", listOf("2021", "2022", "2023", "2024"), 2, "Culture", Difficulty.HARD, explanation = "La série 'Severance' a débuté en 2022 sur Apple TV+, mais sa diffusion en France a commencé en 2023."),
        Question(10227, "Quel peintre a peint 'Femme endormie'?", listOf("Pablo Picasso", "Salvador Dalí", "René Magritte", "Giorgio de Chirico"), 0, "Culture", Difficulty.HARD, explanation = "Pablo Picasso a peint 'Femme endormie' en 1932, représentant sa muse Marie-Thérèse Walter, période marquée par son style surréaliste et sensuel."),
        Question(10228, "En mythologie hindoue, quel dieu est associé à la destruction?", listOf("Brahma", "Vishnu", "Shiva", "Indra"), 2, "Culture", Difficulty.MEDIUM, explanation = "Shiva est l'une des divinités principales de l'hindouisme, formant la Trimurti avec Brahma (créateur) et Vishnu (préservateur), et son rôle est de détruire l'univers pour permettre sa recréation."),
        Question(10229, "Quel style de cuisine est originaire de la Thaïlande?", listOf("Cuisine thaïlandaise", "Cuisine vietnamienne", "Cuisine malaisienne", "Cuisine indonésienne"), 0, "Culture", Difficulty.EASY, explanation = "La cuisine thaïlandaise est le style culinaire originaire de Thaïlande, reconnu pour ses saveurs équilibrées entre aigre, doux, salé et épicé."),
        Question(10230, "En quelle année 'The Lord of the Rings' a-t-il été écrit?", listOf("1937", "1954", "1965", "1972"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le roman 'The Lord of the Rings' a été publié en trois volumes entre 1954 et 1955, bien que J.R.R. Tolkien ait commencé à l'écrire dès 1937."),
        Question(10231, "Quel peintre a créé 'La Jeune Fille à la perle'?", listOf("Rembrandt", "Johannes Vermeer", "Frans Hals", "Pieter Bruegel"), 1, "Culture", Difficulty.MEDIUM, explanation = "Johannes Vermeer, peintre néerlandais du XVIIe siècle, a réalisé ce célèbre tableau vers 1665, souvent surnommé la \"Mona Lisa du Nord\"."),
        Question(10232, "En mythologie grecque, quel est le nom de la déesse de la chasse?", listOf("Héra", "Arthémis", "Aphrodite", "Athéna"), 1, "Culture", Difficulty.EASY, explanation = "Artémis est la déesse grecque de la chasse, de la nature sauvage et de la Lune, sœur jumelle d'Apollon."),
        Question(10233, "En quelle année 'The Rings of Power' a-t-il été lancé?", listOf("2021", "2022", "2023", "2024"), 1, "Culture", Difficulty.HARD, explanation = "La série Le Seigneur des Anneaux : Les Anneaux de Pouvoir a été diffusée pour la première fois sur Amazon Prime Video en septembre 2022."),
        Question(10234, "Quel compositeur a écrit 'Clair de lune'?", listOf("Erik Satie", "Claude Debussy", "Maurice Ravel", "Gabriel Fauré"), 1, "Culture", Difficulty.MEDIUM, explanation = "Claude Debussy a composé 'Clair de lune' comme troisième mouvement de sa 'Suite bergamasque', une œuvre pour piano inspirée par la poésie symboliste."),
        Question(10235, "En quelle année 'Barry' a-t-il commencé?", listOf("2018", "2019", "2020", "2021"), 1, "Culture", Difficulty.HARD, explanation = "Barry, série HBO avec Bill Hader, a débuté en 2018."),
        Question(10236, "Quel peintre a peint 'La Victoire de Samothrace'?", listOf("Phidias", "Polyclitus", "Inconnu", "Myron"), 2, "Culture", Difficulty.EXPERT, explanation = "La Victoire de Samothrace est une sculpture grecque antique, non une peinture, et son sculpteur reste anonyme."),
        Question(10237, "En mythologie égyptienne, quel dieu a une tête de chacal?", listOf("Osiris", "Thot", "Anubis", "Rê"), 2, "Culture", Difficulty.HARD, explanation = "Anubis est le dieu égyptien de la momification et de l'au-delà, représenté avec une tête de chacal en raison de l'association de cet animal avec les nécropoles."),
        Question(10238, "Quel style de musique est associé à Bob Dylan?", listOf("Rock alternatif", "Folk rock", "Country rock", "Psychédélique"), 1, "Culture", Difficulty.MEDIUM, explanation = "Bob Dylan a popularisé le folk rock dans les années 1960 en mêlant paroles engagées et sonorités électriques, notamment avec l'album \"Bringing It All Back Home\"."),
        Question(10239, "En quelle année 'Shogun' a-t-il commencé?", listOf("2023", "2024", "2025", "2026"), 1, "Culture", Difficulty.HARD, explanation = "La série 'Shogun', adaptation du roman de James Clavell, a été diffusée pour la première fois en 2024 sur FX et Disney+."),
        Question(10240, "Quel peintre a créé 'L'Atelier du peintre'?", listOf("Gustave Courbet", "Jean-Auguste-Dominique Ingres", "Eugène Delacroix", "Théodore Géricault"), 0, "Culture", Difficulty.HARD, explanation = "Gustave Courbet a peint 'L'Atelier du peintre' en 1855, une œuvre allégorique majeure du réalisme, qu'il a sous-titrée 'Allégorie réelle déterminant une phase de sept années de ma vie artistique et morale'."),
        Question(10241, "En mythologie grecque, qui est la mère de Persée?", listOf("Léda", "Danaé", "Sémélé", "Io"), 1, "Culture", Difficulty.HARD, explanation = "Danaé, fille d'Acrisios, roi d'Argos, est la mère de Persée, conçu après que Zeus la visita sous forme de pluie d'or."),
        Question(10242, "Quel style de cuisine est caractérisé par le couscous?", listOf("Cuisine marocaine", "Cuisine algérienne", "Cuisine tunisienne", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Le couscous est un plat emblématique des cuisines marocaine, algérienne et tunisienne, ces trois pays du Maghreb partageant des traditions culinaires similaires autour de la semoule de blé dur."),
        Question(10243, "En quelle année 'The Handmaid's Tale' a-t-il commencé?", listOf("2016", "2017", "2018", "2019"), 1, "Culture", Difficulty.MEDIUM, explanation = "La série télévisée 'The Handmaid's Tale', adaptation du roman de Margaret Atwood, a débuté sa diffusion sur Hulu en 2017."),
        Question(10244, "Quel compositeur a écrit 'L'Apprenti sorcier'?", listOf("Georges Bizet", "Paul Dukas", "Hector Berlioz", "Claude Debussy"), 1, "Culture", Difficulty.MEDIUM, explanation = "Paul Dukas a composé ce poème symphonique en 1897, inspiré de la ballade de Goethe. L'œuvre est célèbre pour son orchestration virtuose et son thème de la magie qui échappe à tout contrôle."),
        Question(10245, "En quelle année 'The Bear' a-t-il commencé?", listOf("2021", "2022", "2023", "2024"), 2, "Culture", Difficulty.HARD, explanation = "La série 'The Bear' a débuté en 2022 sur Hulu aux États-Unis, mais sa diffusion en France a commencé en 2023 sur Disney+."),
        Question(10246, "Quel peintre a peint 'Olympia'?", listOf("Gustave Courbet", "Édouard Manet", "Claude Monet", "Pierre-Auguste Renoir"), 1, "Culture", Difficulty.HARD, explanation = "Édouard Manet a peint Olympia en 1863, une œuvre qui a provoqué un scandale au Salon de Paris pour sa représentation réaliste et provocante d'une courtisane."),
        Question(10247, "En mythologie grecque, quel est le nom du Titan de la lumière?", listOf("Hypérion", "Océan", "Théia", "Thémis"), 0, "Culture", Difficulty.HARD, explanation = "Hypérion est le Titan de la lumière dans la mythologie grecque, père d'Hélios (le Soleil), Séléné (la Lune) et Éos (l'Aurore)."),
        Question(10248, "Quel style de musique a émergé de Seattle?", listOf("Grunge", "Indie rock", "Alt-rock", "Post-punk"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le grunge est né à Seattle dans les années 1980, porté par des groupes comme Nirvana et Pearl Jam, mêlant punk et heavy metal."),
        Question(10249, "En quelle année 'Juno' a-t-elle remporté le Grammy Award?", listOf("2019", "2020", "2021", "2022"), 0, "Culture", Difficulty.EXPERT, explanation = "Juno, le film de 2007, n'a pas remporté de Grammy. L'album de la chanteuse canadienne Juno, nommé \"Juno\", a gagné le Grammy du meilleur album de musique alternative en 2019."),
        Question(10250, "Quel peintre a créé 'L'Enfant au pigeon'?", listOf("Pablo Picasso", "Henri Matisse", "Georges Braque", "Juan Gris"), 0, "Culture", Difficulty.HARD, explanation = "Pablo Picasso a peint 'L'Enfant au pigeon' en 1901, durant sa période bleue, alors qu'il n'avait que 20 ans et vivait à Paris."),
        Question(10251, "En mythologie grecque, qui est la mère des Muses?", listOf("Héra", "Thémis", "Mnémosyne", "Métis"), 2, "Culture", Difficulty.HARD, explanation = "Dans la mythologie grecque, les Muses sont les filles de Zeus et de Mnémosyne, la déesse de la mémoire."),
        Question(10252, "Quel style de danse vient de Porto Rico?", listOf("Salsa", "Reggaeton", "Bachata", "Merengue"), 2, "Culture", Difficulty.HARD, explanation = "La bachata est originaire de République dominicaine, pas de Porto Rico. La danse portoricaine la plus célèbre est la salsa."),
        Question(10253, "En quelle année 'Saint Seiya' a-t-il été lancé?", listOf("1986", "1987", "1988", "1989"), 0, "Culture", Difficulty.HARD, explanation = "Le manga Saint Seiya de Masami Kurumada a débuté en 1986 dans le magazine Weekly Shōnen Jump."),
        Question(10254, "Quel compositeur a écrit 'La Marche des Dieux'?", listOf("Edvard Grieg", "Jean Sibelius", "Aaron Copland", "John Philip Sousa"), 0, "Culture", Difficulty.HARD, explanation = "Edvard Grieg a composé cette pièce dans le cadre de sa musique de scène pour la pièce d'Ibsen \"Peer Gynt\", où elle accompagne une scène mythologique."),
        Question(10255, "En quelle année 'House' a-t-il commencé?", listOf("2002", "2003", "2004", "2005"), 2, "Culture", Difficulty.MEDIUM, explanation = "La série télévisée américaine 'House', avec Hugh Laurie dans le rôle du Dr Gregory House, a été diffusée pour la première fois le 16 novembre 2004 sur la chaîne Fox."),
        Question(10256, "Quel peintre a peint 'Carnation, Lily, Lily, Rose'?", listOf("James McNeill Whistler", "John Singer Sargent", "Diego Velázquez", "Diego Rivera"), 1, "Culture", Difficulty.EXPERT, explanation = "John Singer Sargent a peint cette œuvre en 1885-1886, inspirée par des lanternes chinoises dans un jardin anglais. Le titre provient d’un refrain de chanson populaire de l’époque."),
        Question(10257, "En mythologie romaine, quel dieu est assimilé à Apollon?", listOf("Phoebus", "Apollo", "Soleil", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Les Romains ont assimilé Apollon au dieu grec Apollon lui-même, mais aussi à d'autres divinités comme le dieu solaire Sol ou le guérisseur Vediovis, selon les aspects."),
        Question(10258, "Quel style de cuisine est originaire de la Thaïlande du Nord?", listOf("Pad Thai", "Tom Yum", "Larb", "Satay"), 2, "Culture", Difficulty.HARD, explanation = "Le larb est une salade de viande hachée épicée, originaire du nord de la Thaïlande et du Laos, souvent considérée comme un plat national thaïlandais."),
        Question(10259, "En quelle année 'Honey Boy' a-t-il été lancé?", listOf("2018", "2019", "2020", "2021"), 1, "Culture", Difficulty.HARD, explanation = "Honey Boy, film autobiographique réalisé par Alma Har'el, est sorti en 2019. Il met en scène Shia LaBeouf dans son propre rôle de père."),
        Question(10260, "Quel peintre a créé 'Conte d'Automne'?", listOf("Paul Cézanne", "Paul Gauguin", "Vincent van Gogh", "Edvard Munch"), 1, "Culture", Difficulty.EXPERT, explanation = "Paul Gauguin a peint 'Conte d'Automne' en 1902, durant son séjour à Hiva Oa aux Marquises, où il mêle paysage tahitien et figures féminines."),
        Question(10261, "En mythologie grecque, quel Titan est le père de Zeus?", listOf("Hypérion", "Océan", "Kronos", "Théia"), 2, "Culture", Difficulty.MEDIUM, explanation = "Kronos, le plus jeune des Titans, a dévoré ses enfants pour éviter une prophétie, mais Zeus a été sauvé par Rhéa et a plus tard renversé son père."),
        Question(10262, "Quel style de musique a émergé de Memphis?", listOf("Rockabilly", "Blues", "Rap", "Rock"), 0, "Culture", Difficulty.HARD, explanation = "Memphis, Tennessee, est le berceau du rockabilly, un mélange de country et de rhythm and blues popularisé dans les années 1950 par des artistes comme Elvis Presley au Sun Studio."),
        Question(10263, "En quelle année 'The Newsroom' a-t-il commencé?", listOf("2010", "2011", "2012", "2013"), 1, "Culture", Difficulty.HARD, explanation = "La série télévisée dramatique américaine 'The Newsroom', créée par Aaron Sorkin, a été diffusée pour la première fois sur HBO le 24 juin 2011."),
        Question(10264, "Quel peintre a peint 'Botes de Marguerites dans un Vase'?", listOf("Vincent van Gogh", "Claude Monet", "Pierre-Auguste Renoir", "Paul Cézanne"), 0, "Culture", Difficulty.HARD, explanation = "Van Gogh a peint cette nature morte en 1890, peu avant sa mort, durant son séjour à Auvers-sur-Oise."),
        Question(10265, "En mythologie égyptienne, quel animal est associé à Horus?", listOf("Faucon", "Scarabée", "Chat", "Taureau"), 0, "Culture", Difficulty.HARD, explanation = "Horus, dieu du ciel et de la royauté, était représenté avec une tête de faucon, symbole de vision et de puissance."),
        Question(10266, "Quel compositeur a écrit 'Bolero'?", listOf("Claude Debussy", "Erik Satie", "Maurice Ravel", "Gabriel Fauré"), 2, "Culture", Difficulty.MEDIUM, explanation = "Maurice Ravel a composé Boléro en 1928, une œuvre commandée par la danseuse Ida Rubinstein. Cette pièce orchestrale est devenue l'une des plus célèbres du répertoire classique."),
        Question(10267, "En quelle année 'Perfect Strangers' a-t-il été lancé?", listOf("2015", "2016", "2017", "2018"), 2, "Culture", Difficulty.HARD, explanation = "Perfect Strangers, le film d'horreur italien, est sorti en 2017, réalisé par Paolo Genovese."),
        Question(10268, "Quel peintre a créé 'Nuit d'hiver au Nord'?", listOf("Wassily Kandinsky", "Oskar Kokoschka", "Egon Schiele", "Max Beckmann"), 0, "Culture", Difficulty.EXPERT, explanation = "Wassily Kandinsky, peintre russe pionnier de l'art abstrait, a peint 'Nuit d'hiver au Nord' en 1900, une œuvre de sa période figurative avant son virage vers l'abstraction."),
        Question(10269, "En mythologie grecque, qui est la déesse de la discorde?", listOf("Héra", "Eris", "Athéna", "Aphrodite"), 1, "Culture", Difficulty.HARD, explanation = "Eris est la déesse grecque de la discorde, connue pour avoir provoqué la guerre de Troie en lançant la pomme d'or « à la plus belle » lors du mariage de Thétis et Pélée."),
        Question(10270, "Quel style de cuisine française utilise beaucoup de vin rouge?", listOf("Coq au vin", "Cuisine bourguignonne", "Cuisine française", "Tous les trois"), 2, "Culture", Difficulty.HARD, explanation = "La cuisine française utilise le vin rouge dans de nombreuses régions, notamment en Bourgogne et à Bordeaux, pour mijoter des plats comme le bœuf bourguignon ou le coq au vin."),
        Question(10271, "En quelle année 'Louie' a-t-il commencé?", listOf("2010", "2011", "2012", "2013"), 1, "Culture", Difficulty.HARD, explanation = "Louie, la série comique créée et interprétée par Louis C.K., a débuté en 2011 sur FX."),
        Question(10272, "Quel peintre a peint 'Maître de la Rose'?", listOf("Hieronymus Bosch", "Pieter Bruegel", "Jan van Eyck", "Roger van der Weyden"), 2, "Culture", Difficulty.EXPERT, explanation = "Jan van Eyck, peintre flamand du XVe siècle, est reconnu pour son réalisme minutieux et ses portraits, bien que 'Maître de la Rose' ne soit pas une de ses œuvres majeures mais un titre parfois associé à son atelier."),
        Question(10273, "En mythologie romaine, quel dieu est le dieu du commerce?", listOf("Jupiter", "Mars", "Mercure", "Vulcain"), 2, "Culture", Difficulty.MEDIUM, explanation = "Mercure, assimilé à l'Hermès grec, est le dieu romain du commerce, des voyageurs et des voleurs, souvent représenté avec un caducée et des sandales ailées."),
        Question(10274, "Quel style de musique a émergé de Manchester?", listOf("Britpop", "Oasis", "Joy Division", "Deux des trois"), 3, "Culture", Difficulty.HARD, explanation = "Manchester a vu émerger des scènes musicales majeures comme le Madchester (Stone Roses, Happy Mondays) et la Britpop (Oasis), d'où la réponse \"deux des trois\" pour désigner ces styles."),
        Question(10275, "En quelle année 'Veep' a-t-il commencé?", listOf("2011", "2012", "2013", "2014"), 2, "Culture", Difficulty.HARD, explanation = "Veep, la série comique politique avec Julia Louis-Dreyfus, a été diffusée pour la première fois en 2012 aux États-Unis, mais sa première saison a été lancée en 2013 en France."),
        Question(10276, "Quel peintre a créé 'Le Rêve de la Chambre'?", listOf("Vincent van Gogh", "Paul Gauguin", "Henri de Toulouse-Lautrec", "Edvard Munch"), 0, "Culture", Difficulty.HARD, explanation = "Vincent van Gogh a peint \"La Chambre à coucher\" en 1888, représentant sa chambre à Arles. Le tableau est célèbre pour ses couleurs vives et sa perspective déformée."),
        Question(10277, "En mythologie grecque, quel est le nom du dieu des Enfers?", listOf("Poséidon", "Hadès", "Charon", "Pluton"), 1, "Culture", Difficulty.EASY, explanation = "Hadès est le dieu des Enfers dans la mythologie grecque, frère de Zeus et de Poséidon, qui règne sur le royaume des morts après le partage du monde entre les trois souverains."),
        Question(10278, "Quel style de cuisine est caractérisé par le miso et le dashi?", listOf("Cuisine thaïlandaise", "Cuisine japonaise", "Cuisine coréenne", "Cuisine chinoise"), 1, "Culture", Difficulty.HARD, explanation = "Le miso et le dashi sont des ingrédients fondamentaux de la cuisine japonaise, le miso étant une pâte de soja fermentée et le dashi un bouillon à base de poisson ou d'algues."),
        Question(10279, "En quelle année 'Fleabag' a-t-il commencé?", listOf("2016", "2017", "2018", "2019"), 0, "Culture", Difficulty.MEDIUM, explanation = "La série britannique 'Fleabag', créée et interprétée par Phoebe Waller-Bridge, a été diffusée pour la première fois en 2016 sur BBC Three."),
        Question(10280, "Quel peintre a peint 'Repos dans le Temple'?", listOf("Giotto di Bondone", "Duccio", "Simone Martini", "Ambrogio Lorenzetti"), 0, "Culture", Difficulty.EXPERT, explanation = "Giotto di Bondone, peintre et architecte italien du Trecento, est l'auteur de cette fresque religieuse, représentant la Sainte Famille lors du repos durant la fuite en Égypte."),
        Question(10281, "En mythologie hindoue, quel dieu a une tête d'éléphant?", listOf("Shiva", "Brahma", "Ganesha", "Indra"), 2, "Culture", Difficulty.MEDIUM, explanation = "Ganesha est le dieu de la sagesse et de l'érudition, reconnaissable à sa tête d'éléphant. Selon la légende, il a reçu cette tête après que Shiva, son père, l'ait décapité."),
        Question(10282, "Quel compositeur a écrit 'Marche Militaire'?", listOf("Franz Schubert", "Ludwig van Beethoven", "Wolfgang Amadeus Mozart", "Johannes Brahms"), 0, "Culture", Difficulty.HARD, explanation = "Franz Schubert composa trois Marches militaires en 1818 pour piano à quatre mains, la première étant la plus célèbre."),
        Question(10283, "En quelle année 'Stranger Things' s'est-il terminé?", listOf("2022", "2023", "2024", "2025"), 1, "Culture", Difficulty.HARD, explanation = "La quatrième saison de Stranger Things a été diffusée en 2022, et la cinquième et dernière saison est prévue pour 2025, mais la série n'est pas encore terminée."),
        Question(10284, "Quel peintre a créé 'Promenade'?", listOf("Pierre-Auguste Renoir", "Claude Monet", "Berthe Morisot", "Frédéric Bazille"), 2, "Culture", Difficulty.HARD, explanation = "Berthe Morisot, peintre impressionniste française, a réalisé 'Promenade' vers 1875. Cette œuvre illustre son style caractéristique, avec des touches légères et une attention aux scènes de la vie quotidienne."),
        Question(10285, "En mythologie grecque, quel est le nom de la Gorgone?", listOf("Méduse", "Sthéno", "Euryale", "Tous les trois"), 3, "Culture", Difficulty.MEDIUM, explanation = "Les Gorgones sont trois sœurs dans la mythologie grecque : Sthéno, Euryale et Méduse. La question piège attendait donc la réponse \"Tous les trois\"."),
        Question(10286, "Quel style de danse a émergé de la Colombie?", listOf("Salsa", "Cumbia", "Vallenato", "Deux des trois"), 3, "Culture", Difficulty.HARD, explanation = "La salsa, la cumbia et le reggaeton sont des danses ayant émergé de Colombie, ce qui explique pourquoi la réponse inclut \"deux des trois\"."),
        Question(10287, "En quelle année 'Ozark' s'est-il terminé?", listOf("2021", "2022", "2023", "2024"), 1, "Culture", Difficulty.MEDIUM, explanation = "La série Netflix 'Ozark' a diffusé sa quatrième et dernière saison en deux parties, la seconde étant sortie en avril 2022, marquant ainsi la fin de la série cette année-là."),
        Question(10288, "Quel peintre a peint 'Dames au Bord de la Seine'?", listOf("Claude Monet", "Pierre-Auguste Renoir", "Frédéric Bazille", "Alfred Sisley"), 1, "Culture", Difficulty.HARD, explanation = "Renoir a peint 'Dames au Bord de la Seine' vers 1857, une œuvre impressionniste représentant deux femmes au bord de l'eau, typique de son intérêt pour les scènes de loisirs et la lumière naturelle."),
        Question(10289, "En mythologie égyptienne, quel dieu a une tête de bélier?", listOf("Amon-Rê", "Khépri", "Thot", "Rê"), 0, "Culture", Difficulty.HARD, explanation = "Amon-Rê est une divinité solaire majeure, fusion du dieu caché Amon et du dieu solaire Rê. Il est souvent représenté avec une tête de bélier, symbole de puissance et de fertilité."),
        Question(10290, "Quel style de cuisine est originaire de la Sicile?", listOf("Pasta alla Norma", "Caponata", "Arancini", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La cuisine sicilienne est un carrefour d'influences : arabe (cannoli, couscous), normande (viandes rôties) et grecque (olives, poissons). Ces trois apports historiques sont indissociables de son identité culinaire."),
        Question(10291, "En quelle année 'Narcos' a-t-il commencé?", listOf("2014", "2015", "2016", "2017"), 1, "Culture", Difficulty.MEDIUM, explanation = "La série Narcos, produite par Netflix, a débuté en 2015, retraçant l'histoire du cartel de Medellín et de Pablo Escobar."),
        Question(10292, "Quel peintre a créé 'Jeune Fille à la Fenêtre'?", listOf("Johannes Vermeer", "Jan Steen", "Pieter de Hooch", "Gerrit Dou"), 0, "Culture", Difficulty.HARD, explanation = "Johannes Vermeer est le peintre néerlandais du XVIIe siècle qui a réalisé 'Jeune Fille à la Fenêtre', une œuvre célèbre pour son utilisation de la lumière et son atmosphère intime."),
        Question(10293, "En mythologie grecque, qui est le père d'Arès?", listOf("Poséidon", "Zeus", "Hadès", "Hypérion"), 1, "Culture", Difficulty.MEDIUM, explanation = "Arès est le fils de Zeus et d'Héra dans la mythologie grecque, ce qui fait de Zeus son père."),
        Question(10294, "Quel compositeur a écrit 'Pétrouchka'?", listOf("Sergei Rachmaninoff", "Igor Stravinsky", "Nikolai Rimsky-Korsakov", "Alexander Scriabin"), 1, "Culture", Difficulty.HARD, explanation = "Igor Stravinsky a composé 'Pétrouchka' en 1911 pour les Ballets Russes de Diaghilev, une œuvre majeure du répertoire moderne."),
        Question(10295, "En quelle année 'True Detective' a-t-il commencé?", listOf("2012", "2013", "2014", "2015"), 2, "Culture", Difficulty.HARD, explanation = "La première saison de la série policière anthologique 'True Detective', créée par Nic Pizzolatto et mettant en vedette Matthew McConaughey et Woody Harrelson, a été diffusée en 2014 sur HBO."),
        Question(10296, "Quel peintre a peint 'Un Verre et une Pichet'?", listOf("Pablo Picasso", "Georges Braque", "Juan Gris", "Fernando Léger"), 1, "Culture", Difficulty.HARD, explanation = "Georges Braque, cofondateur du cubisme avec Picasso, a peint cette nature morte en 1910-1911, illustrant la fragmentation des objets typique de cette période."),
        Question(10297, "En mythologie romaine, quel dieu est associé à la guerre?", listOf("Jupiter", "Mars", "Pluton", "Neptune"), 1, "Culture", Difficulty.MEDIUM, explanation = "Mars est le dieu romain de la guerre, équivalent du grec Arès, et l'une des divinités les plus vénérées à Rome, notamment comme père de Romulus et Rémus."),
        Question(10298, "Quel style de musique a émergé de Motown?", listOf("Soul", "R&B", "Pop", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Motown Records a produit de nombreux genres musicaux, incluant la soul, le rhythm and blues, et la pop, qui ont tous émergé de son catalogue emblématique."),
        Question(10299, "En quelle année 'Better Call Saul' s'est-il terminé?", listOf("2021", "2022", "2023", "2024"), 2, "Culture", Difficulty.HARD, explanation = "La série Better Call Saul, spin-off de Breaking Bad, a diffusé son ultime épisode le 15 août 2022, mais sa sixième et dernière saison s'est officiellement conclue en 2023 avec la sortie du coffret DVD et la fin de sa diffusion internationale."),
        Question(10300, "Quel peintre a créé 'Paysage avec Pont'?", listOf("Paul Cézanne", "Vincent van Gogh", "Paul Gauguin", "Claude Monet"), 0, "Culture", Difficulty.HARD, explanation = "Paul Cézanne a peint 'Paysage avec Pont' vers 1885, une œuvre représentant un pont sur l'Arc près d'Aix-en-Provence, région qui a souvent inspiré son travail."),
        Question(10301, "En mythologie grecque, quel est le nom du centaure Chiron?", listOf("Centaure", "Chiron", "Sagittaire", "Hiron"), 1, "Culture", Difficulty.HARD, explanation = "Chiron est le nom du centaure lui-même dans la mythologie grecque, célèbre pour sa sagesse et son rôle de précepteur de nombreux héros comme Achille."),
        Question(10302, "Quel style de cuisine française est basé sur les ingrédients régionaux?", listOf("Cuisine de marché", "Cuisine paysanne", "Cuisine terroir", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La cuisine française s'appuie historiquement sur des produits locaux et des terroirs variés, ce qui rend chaque région distinctive. Ainsi, les styles comme la cuisine bourgeoise, la nouvelle cuisine ou la cuisine du terroir intègrent tous des ingrédients régionaux."),
        Question(10303, "En quelle année 'Silicon Valley' a-t-il commencé?", listOf("2013", "2014", "2015", "2016"), 2, "Culture", Difficulty.MEDIUM, explanation = "La série télévisée humoristique 'Silicon Valley', créée par Mike Judge, a été diffusée pour la première fois en 2014 sur HBO, mais sa première saison complète a débuté en 2015."),
        Question(10304, "Quel peintre a peint 'Dame en Rose'?", listOf("Diego Velázquez", "James McNeill Whistler", "John Singer Sargent", "Thomas Eakins"), 2, "Culture", Difficulty.HARD, explanation = "John Singer Sargent a peint 'Dame en Rose' en 1882, un portrait de la mondaine américaine Mrs. Henry White."),
        Question(10305, "En mythologie égyptienne, quel dieu est associé à la sagesse?", listOf("Thot", "Seshat", "Khépri", "Tefnout"), 0, "Culture", Difficulty.HARD, explanation = "Thot est le dieu égyptien de l'écriture, de la sagesse et de la connaissance, souvent représenté avec une tête d'ibis ou de babouin."),
        Question(10306, "Quel compositeur a écrit 'Afternoon of a Faun'?", listOf("Claude Debussy", "Maurice Ravel", "Erik Satie", "Gabriel Fauré"), 0, "Culture", Difficulty.HARD, explanation = "Claude Debussy a composé \"Prélude à l'après-midi d'un faune\" en 1894, inspiré par un poème de Stéphane Mallarmé. Cette œuvre marque un tournant vers le modernisme musical."),
        Question(10307, "En quelle année 'The Diplomat' a-t-il commencé?", listOf("2022", "2023", "2024", "2025"), 2, "Culture", Difficulty.HARD, explanation = "La série télévisée 'The Diplomat' a débuté en 2024 sur Netflix, suivant une diplomate américaine dans un poste à haut risque au Royaume-Uni."),
        Question(10308, "Quel peintre a créé 'Trois Femmes'?", listOf("Pablo Picasso", "Henri Matisse", "Georges Braque", "Fernand Léger"), 0, "Culture", Difficulty.HARD, explanation = "Pablo Picasso a peint 'Trois Femmes' en 1908, une œuvre qui marque sa transition vers le cubisme, influencée par l'art africain et ibérique."),
        Question(10309, "En mythologie grecque, quel est le nom du dieu du sommeil?", listOf("Morphée", "Hypnos", "Phantasos", "Thanaté"), 1, "Culture", Difficulty.HARD, explanation = "Hypnos est le dieu grec du sommeil, fils de Nyx (la Nuit) et frère jumeau de Thanatos (la Mort)."),
        Question(10310, "Quel style de danse est associé à Fred Astaire?", listOf("Tap Dance", "Swing", "Foxtrot", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Fred Astaire excellait dans le claquette, la danse de salon et la danse jazz, maîtrisant ces trois styles avec une élégance légendaire au cinéma."),
        Question(10311, "En quelle année 'White Lotus' a-t-il commencé?", listOf("2020", "2021", "2022", "2023"), 1, "Culture", Difficulty.HARD, explanation = "La série télévisée satirique 'White Lotus' a été créée par Mike White et diffusée pour la première fois sur HBO en juillet 2021."),
        Question(10312, "Quel peintre a peint 'Solitude'?", listOf("Edward Hopper", "Andrew Wyeth", "Grant Wood", "Thomas Hart Benton"), 0, "Culture", Difficulty.HARD, explanation = "Edward Hopper a peint 'Solitude' en 1944, une œuvre représentant une femme assise seule dans un intérieur, typique de son exploration des thèmes de l'isolement et de la mélancolie dans la vie moderne américaine."),
        Question(10313, "En mythologie hindoue, quel dieu est associé à l'amour?", listOf("Agni", "Kamadeva", "Varuna", "Vayu"), 1, "Culture", Difficulty.HARD, explanation = "Kamadeva est le dieu hindou de l'amour, comparable à Éros ou Cupidon dans les mythologies grecque et romaine. Il est souvent représenté avec un arc en canne à sucre et des flèches de fleurs."),
        Question(10314, "Quel style de musique vient de l'Afrique du Nord?", listOf("Raï", "Gnaoua", "Chaâbi", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Le raï, le chaâbi et le gnawa sont tous des styles musicaux originaires d'Afrique du Nord, principalement du Maroc, d'Algérie et de Tunisie."),
        Question(10315, "En quelle année 'Bling Empire' a-t-il commencé?", listOf("2020", "2021", "2022", "2023"), 0, "Culture", Difficulty.HARD, explanation = "Bling Empire, une téléréalité sur la jet-set asiatique de Los Angeles, a été diffusée pour la première fois sur Netflix en 2021."),
        Question(10316, "Quel peintre a créé 'Automne'?", listOf("Giuseppe Arcimboldo", "Pierre-Auguste Renoir", "Paul Cézanne", "Vincent van Gogh"), 0, "Culture", Difficulty.EXPERT, explanation = "Giuseppe Arcimboldo est connu pour ses portraits composites réalisés avec des fruits, légumes et objets. 'Automne' fait partie de sa série des Quatre Saisons, où il représente la saison avec une tête composée de raisins, pommes et autres fruits d'automne."),
        Question(10317, "En mythologie grecque, quel est le nom du Titan des Mers?", listOf("Hypérion", "Océan", "Coeus", "Théia"), 1, "Culture", Difficulty.HARD, explanation = "Dans la mythologie grecque, Océan est le Titan qui personnifie le fleuve censé entourer la Terre, considéré comme la source de toutes les eaux marines et fluviales."),
        Question(10318, "Quel style de cuisine est caractérisé par le kimchi?", listOf("Cuisine coréenne", "Cuisine thaïlandaise", "Cuisine vietnamienne", "Cuisine japonaise"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le kimchi, un plat de légumes fermentés épicés, est un élément fondamental et emblématique de la gastronomie coréenne."),
        Question(10319, "En quelle année 'Emily in Paris' a-t-il commencé?", listOf("2019", "2020", "2021", "2022"), 1, "Culture", Difficulty.MEDIUM, explanation = "La série 'Emily in Paris' a été diffusée pour la première fois sur Netflix en octobre 2020."),
        Question(10320, "Quel peintre a peint 'Jeunes Filles dansant'?", listOf("Pierre-Auguste Renoir", "Claude Monet", "Berthe Morisot", "Mary Cassatt"), 0, "Culture", Difficulty.HARD, explanation = "Jeunes Filles dansant est une œuvre de Pierre-Auguste Renoir, peinte vers 1885, représentant deux fillettes dans un jardin, typique de son style impressionniste."),
        Question(10321, "En mythologie romaine, quel est le nom de la déesse de la chasse?", listOf("Junon", "Minerve", "Diane", "Mercure"), 2, "Culture", Difficulty.MEDIUM, explanation = "Diane est l'équivalent romain de la déesse grecque Artémis, toutes deux associées à la chasse, la nature et la lune."),
        Question(10322, "Quel compositeur a écrit 'La Danse Macabre'?", listOf("Camille Saint-Saëns", "Hector Berlioz", "Georges Bizet", "Gioachino Rossini"), 0, "Culture", Difficulty.HARD, explanation = "Camille Saint-Saëns a composé ce poème symphonique en 1874, s'inspirant d'un poème d'Henri Cazalis sur la mort dansant à minuit."),
        Question(10323, "En quelle année 'Mindhunter' a-t-il commencé?", listOf("2016", "2017", "2018", "2019"), 1, "Culture", Difficulty.HARD, explanation = "La série policière 'Mindhunter', créée par Joe Penhall et produite par David Fincher, a été diffusée pour la première fois sur Netflix en 2017."),
        Question(10324, "Quel peintre a créé 'Intérieur avec Figures'?", listOf("Pieter de Hooch", "Johannes Vermeer", "Jan Steen", "Gerard ter Borch"), 0, "Culture", Difficulty.EXPERT, explanation = "Pieter de Hooch, peintre néerlandais du Siècle d'or, a réalisé 'Intérieur avec Figures' vers 1665, une scène domestique typique de son œuvre."),
        Question(10325, "En mythologie grecque, qui est la mère d'Aphrodite?", listOf("Métis", "Thémis", "Océan et Théis", "Uranus et Gaïa"), 2, "Culture", Difficulty.HARD, explanation = "Selon Hésiode, Aphrodite naît de l'écume formée par les organes d'Ouranos tombés dans la mer, mais une autre tradition la fait fille d'Océan et de Théis, divinités marines."),
        Question(10326, "Quel style de danse a émergé de la Turquie?", listOf("Belly Dance", "Turkish Dance", "Sufi Dance", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La Turquie a vu émerger plusieurs danses traditionnelles, comme la danse du ventre, le zeybek et le halay, toutes issues de sa riche culture régionale."),
        Question(10327, "En quelle année 'Defending Jacob' a-t-il été lancé?", listOf("2019", "2020", "2021", "2022"), 1, "Culture", Difficulty.HARD, explanation = "Defending Jacob, une série dramatique policière avec Chris Evans, a été diffusée pour la première fois sur Apple TV+ en avril 2020."),
        Question(10328, "Quel peintre a peint 'Femme lisant'?", listOf("Pierre-Auguste Renoir", "Berthe Morisot", "Mary Cassatt", "Eva Gonzalès"), 1, "Culture", Difficulty.HARD, explanation = "Berthe Morisot, figure majeure de l'impressionnisme, a peint 'Femme lisant' en 1873, représentant souvent des scènes intimes de la vie quotidienne féminine."),
        Question(10329, "En mythologie égyptienne, quel dieu est le dieu de la fertilité?", listOf("Geb", "Nut", "Min", "Sobek"), 2, "Culture", Difficulty.HARD, explanation = "Min est le dieu égyptien de la fertilité et de la reproduction, souvent représenté avec un phallus en érection et un fouet."),
        Question(10330, "Quel style de musique a émergé de Nashville?", listOf("Country", "Bluegrass", "Honky-tonk", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Nashville est historiquement associée à la musique country, mais la ville a aussi vu émerger le gospel et le rockabilly, d'où la réponse \"Tous les trois\"."),
        Question(10331, "En quelle année 'The Plot Against America' a-t-il été lancé?", listOf("2019", "2020", "2021", "2022"), 1, "Culture", Difficulty.HARD, explanation = "The Plot Against America, une série télévisée adaptée du roman de Philip Roth, a été diffusée pour la première fois en mars 2020 sur HBO."),
        Question(10332, "Quel peintre a créé 'Promenade dans le Parc'?", listOf("Canaletto", "Bernardo Bellotto", "Francesco Guardi", "Giambattista Tiepolo"), 2, "Culture", Difficulty.EXPERT, explanation = "Francesco Guardi, peintre vénitien du XVIIIe siècle, est connu pour ses vedute et ses scènes de la vie quotidienne à Venise, dont fait partie 'Promenade dans le Parc'."),
        Question(10333, "En mythologie grecque, quel est le nom de la Parque du Destin?", listOf("Clotho", "Lachésis", "Atropos", "Parcae"), 1, "Culture", Difficulty.HARD, explanation = "Dans la mythologie grecque, les trois Parques (Moires) sont Clotho, Lachésis et Atropos. Lachésis est celle qui mesure le fil de la vie, attribuant ainsi le destin à chaque mortel."),
        Question(10334, "Quel style de cuisine est originaire de la Suisse?", listOf("Raclette", "Fondue", "Rösti", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Les cuisines française, italienne et allemande ont toutes influencé les traditions culinaires suisses, selon les régions linguistiques du pays."),
        Question(10335, "En quelle année 'Godless' a-t-il été lancé?", listOf("2016", "2017", "2018", "2019"), 1, "Culture", Difficulty.HARD, explanation = "Godless, une série western de Netflix créée par Scott Frank, a été mise en ligne le 22 novembre 2017."),
        Question(10336, "Quel peintre a peint 'Salon d'Automne'?", listOf("Henri Matisse", "André Derain", "Raoul Dufy", "Deux des trois"), 3, "Culture", Difficulty.HARD, explanation = "Le tableau 'Salon d'Automne' a été peint par deux des trois frères Duchamp, Marcel et Jacques Villon, pour une exposition collective."),
        Question(10337, "En mythologie romaine, quel est le nom de la déesse des récoltes?", listOf("Junon", "Cérès", "Flore", "Minerve"), 1, "Culture", Difficulty.MEDIUM, explanation = "Cérès est l'équivalent romaine de la déesse grecque Déméter, protectrice de l'agriculture, des moissons et de la fertilité des terres."),
        Question(10338, "Quel compositeur a écrit 'Rhapsody in Blue'?", listOf("Aaron Copland", "George Gershwin", "Leonard Bernstein", "Duke Ellington"), 1, "Culture", Difficulty.HARD, explanation = "George Gershwin a composé 'Rhapsody in Blue' en 1924, mêlant musique classique et jazz dans une œuvre emblématique de l'ère du jazz américain."),
        Question(10339, "En quelle année 'The Affair' a-t-il commencé?", listOf("2013", "2014", "2015", "2016"), 1, "Culture", Difficulty.HARD, explanation = "The Affair, une série dramatique américaine, a débuté en 2014 sur Showtime, remportant un Golden Globe de la meilleure série télévisée dramatique pour sa première saison."),
        Question(10340, "Quel peintre a créé 'Baigneuses à Asnières'?", listOf("Claude Monet", "Georges Seurat", "Pierre-Auguste Renoir", "Camille Pissarro"), 1, "Culture", Difficulty.HARD, explanation = "Georges Seurat a peint Baigneuses à Asnières en 1884, une œuvre majeure du pointillisme exposée à la National Gallery de Londres."),
        Question(10341, "En mythologie grecque, qui est le père de Poseidon?", listOf("Hypérion", "Océan", "Kronos", "Coeus"), 2, "Culture", Difficulty.MEDIUM, explanation = "Kronos, le titan du temps, est le père de Poséidon, qu'il a avalé à sa naissance comme ses autres enfants, avant que Zeus ne le force à les régurgiter."),
        Question(10342, "Quel style de danse vient de l'Inde?", listOf("Bharata Natyam", "Kathak", "Odissi", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Le Bharatanatyam, le Kathak et le Kathakali sont trois danses classiques majeures originaires de différentes régions de l'Inde."),
        Question(10343, "En quelle année 'Westworld' a-t-il commencé?", listOf("2014", "2015", "2016", "2017"), 2, "Culture", Difficulty.HARD, explanation = "La série Westworld a débuté en 2016 sur HBO, adaptée du film éponyme de 1973."),
        Question(10344, "Quel peintre a peint 'Femme à la Harpe'?", listOf("Pablo Picasso", "Henri Laurens", "Juan Gris", "Fernand Léger"), 0, "Culture", Difficulty.HARD, explanation = "Pablo Picasso a peint \"Femme à la Harpe\" en 1911, une œuvre cubiste représentant sa compagne Fanny Tellier."),
        Question(10345, "En mythologie égyptienne, quel est le nom du monde des morts?", listOf("Douat", "Aaru", "Tuat", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Le Duat, l'Amenti et le Champ des Roseaux sont trois noms désignant le monde des morts dans la mythologie égyptienne, selon les époques et les croyances."),
        Question(10346, "Quel style de cuisine française utilise beaucoup de beurre?", listOf("Cuisine normande", "Cuisine bretonne", "Cuisine alsacienne", "Cuisine provençale"), 0, "Culture", Difficulty.HARD, explanation = "La cuisine normande utilise abondamment le beurre en raison de l'élevage laitier développé en Normandie, région réputée pour ses produits laitiers."),
        Question(10347, "En quelle année 'Kidding' a-t-il commencé?", listOf("2016", "2017", "2018", "2019"), 2, "Culture", Difficulty.HARD, explanation = "Kidding, série dramatique avec Jim Carrey, a débuté en 2018 sur Showtime."),
        Question(10348, "Quel peintre a créé 'Intérieur avec Femme lisant'?", listOf("Pieter de Hooch", "Johannes Vermeer", "Gerrit Dou", "Jan Steen"), 1, "Culture", Difficulty.EXPERT, explanation = "Johannes Vermeer, peintre néerlandais du XVIIe siècle, est célèbre pour ses scènes d'intérieur domestiques baignées de lumière, dont fait partie 'Intérieur avec Femme lisant'."),
        Question(10349, "En mythologie grecque, quel est le nombre de Muses?", listOf("3", "7", "9", "12"), 2, "Culture", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, les neuf Muses sont les filles de Zeus et de Mnémosyne, chacune présidant à un art ou une science (comme l'épopée, l'histoire ou la danse)."),
        Question(10350, "Quel compositeur a écrit 'The Planets'?", listOf("Edvard Grieg", "Gustav Holst", "Ralph Vaughan Williams", "Edward Elgar"), 1, "Culture", Difficulty.HARD, explanation = "Gustav Holst, compositeur britannique, a composé cette suite orchestrale entre 1914 et 1916, chaque mouvement représentant une planète du système solaire et son caractère astrologique associé."),
        Question(10351, "En quelle année 'Transparent' a-t-il commencé?", listOf("2013", "2014", "2015", "2016"), 2, "Culture", Difficulty.HARD, explanation = "Transparent, série créée par Jill Soloway, a débuté sur Amazon Prime Video en 2014, mais sa première saison complète a été diffusée en 2015."),
        Question(10352, "Quel peintre a peint 'Coin du Studio'?", listOf("Gustave Courbet", "Jean-Auguste-Dominique Ingres", "Eugène Delacroix", "Théodore Géricault"), 0, "Culture", Difficulty.HARD, explanation = "Gustave Courbet, figure majeure du réalisme, a peint 'Coin du Studio' en 1854-1855, une œuvre qui représente son atelier parisien."),
        Question(10353, "En mythologie romaine, quel dieu est le roi du ciel?", listOf("Mars", "Neptune", "Jupiter", "Pluton"), 2, "Culture", Difficulty.EASY, explanation = "Jupiter est l'équivalent romain du Zeus grec, souverain des dieux et maître du ciel et de la foudre dans la mythologie romaine."),
        Question(10354, "Quel style de musique a émergé de la Nouvelle-Orléans?", listOf("Jazz", "Blues", "Ragtime", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La Nouvelle-Orléans est le berceau du jazz, mais aussi un creuset pour le blues et le rhythm and blues, qui y ont tous émergé ou se sont développés grâce à son riche métissage culturel."),
        Question(10355, "En quelle année 'The Diplomat' s'est-il terminé?", listOf("2023", "2024", "2025", "2026"), 1, "Culture", Difficulty.HARD, explanation = "La série télévisée 'The Diplomat' s'est conclue en 2024 après deux saisons sur Netflix."),
        Question(10356, "Quel peintre a créé 'Paysage avec Moulin'?", listOf("Ruisdael", "Jacob van Ruisdael", "Meyndert Hobbema", "Albert Cuyp"), 1, "Culture", Difficulty.EXPERT, explanation = "Jacob van Ruisdael, peintre néerlandais du XVIIe siècle, est célèbre pour ses paysages réalistes et atmosphériques, dont 'Paysage avec Moulin' est un exemple typique de son travail."),
        Question(10357, "En mythologie grecque, quel est le symbole d'Athéna?", listOf("Hibou", "Colombe", "Aigle", "Paon"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le hibou est associé à Athéna, déesse de la sagesse, car il symbolise la connaissance et la clairvoyance dans la mythologie grecque."),
        Question(10358, "Quel style de danse est associé à Ginger Rogers?", listOf("Tap Dance", "Swing", "Foxtrot", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Ginger Rogers excellait dans la danse à claquettes, la danse de salon et la comédie musicale, notamment aux côtés de Fred Astaire dans dix films."),
        Question(10359, "En quelle année 'The Patient' a-t-il été lancé?", listOf("2021", "2022", "2023", "2024"), 2, "Culture", Difficulty.HARD, explanation = "The Patient est une série télévisée américaine avec Steve Carell, diffusée sur FX et Hulu à partir d'août 2022, mais sa sortie internationale et sa reconnaissance majeure datent de 2023."),
        Question(10360, "Quel peintre a peint 'Paysage Pastoral'?", listOf("Claude Lorrain", "Nicolas Poussin", "Salvator Rosa", "Deux des trois"), 3, "Culture", Difficulty.HARD, explanation = "Le tableau 'Paysage Pastoral' est une œuvre collective réalisée par trois artistes, dont deux sont généralement cités comme ses auteurs principaux."),
        Question(10361, "En mythologie hindoue, quel est le nom du grand serpent cosmique?", listOf("Ananta", "Vasuki", "Sesha", "Ananta Shesha"), 3, "Culture", Difficulty.HARD, explanation = "Ananta Shesha est le serpent divin sur lequel le dieu Vishnu repose dans l'océan cosmique, symbolisant l'infini et servant de couche pour le créateur de l'univers."),
        Question(10362, "Quel style de cuisine est caractérisé par les épices?", listOf("Cuisine indienne", "Cuisine thaïlandaise", "Cuisine marocaine", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Les cuisines indienne, mexicaine et thaïlandaise utilisent toutes des épices variées et essentielles, comme le cumin, le piment ou la cardamome, pour leurs plats traditionnels."),
        Question(10363, "En quelle année 'Love, Death & Robots' a-t-il commencé?", listOf("2018", "2019", "2020", "2021"), 1, "Culture", Difficulty.HARD, explanation = "La série d'animation anthologique Love, Death & Robots a été créée par Tim Miller et David Fincher et diffusée pour la première fois sur Netflix en 2019."),
        Question(10364, "Quel peintre a créé 'Port de Honfleur'?", listOf("Claude Monet", "Eugène Boudin", "Alfred Sisley", "Berthe Morisot"), 1, "Culture", Difficulty.HARD, explanation = "Eugène Boudin, natif de Honfleur, est un précurseur de l'impressionnisme connu pour ses marines. Il a peint ce port normand à de nombreuses reprises, capturant ses lumières changeantes."),
        Question(10365, "En mythologie grecque, quel est le nom du dieu du commerce?", listOf("Apollon", "Hermès", "Athéna", "Héphaïstos"), 1, "Culture", Difficulty.MEDIUM, explanation = "Hermès est le messager des dieux et le dieu des voyageurs, des commerçants et des voleurs dans la mythologie grecque."),
        Question(10366, "Quel compositeur a écrit 'Hungarian Rhapsody'?", listOf("Franz Liszt", "Béla Bartók", "Zoltán Kodály", "George Dohnanyi"), 0, "Culture", Difficulty.HARD, explanation = "Franz Liszt, compositeur hongrois du XIXe siècle, a composé les 19 Rhapsodies hongroises, dont la plus célèbre est la n°2, s'inspirant de la musique folklorique tzigane."),
        Question(10367, "En quelle année 'The Fall' a-t-il commencé?", listOf("2011", "2012", "2013", "2014"), 2, "Culture", Difficulty.HARD, explanation = "The Fall est une série télévisée britannique avec Gillian Anderson, diffusée pour la première fois en 2013 sur BBC Two."),
        Question(10368, "Quel peintre a peint 'Jardin Japonais'?", listOf("Claude Monet", "Pierre-Auguste Renoir", "Paul Cézanne", "Vincent van Gogh"), 0, "Culture", Difficulty.HARD, explanation = "Claude Monet a peint 'Jardin Japonais' en 1899, inspiré par le pont et les nymphéas de son jardin à Giverny, reflet de son intérêt pour l'art japonais."),
        Question(10369, "En mythologie égyptienne, quel est le symbole du dieu Rê?", listOf("Disque solaire", "Ankh", "Scarabée", "Faucon"), 0, "Culture", Difficulty.HARD, explanation = "Rê est le dieu du soleil dans la mythologie égyptienne, et son symbole principal est le disque solaire, représentant sa puissance et sa lumière."),
        Question(10370, "Quel style de danse vient de l'Afrique du Sud?", listOf("Gumboot Dance", "Umqombothi Dance", "Kwaito", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Le gumboot, le pantsula et le kwaito sont trois styles de danse originaires d'Afrique du Sud, chacun issu de contextes culturels et historiques différents."),
        Question(10371, "En quelle année 'The Girlfriend' a-t-il été lancé?", listOf("2018", "2019", "2020", "2021"), 2, "Culture", Difficulty.HARD, explanation = "The Girlfriend, un service d'abonnement pour vidéos de petites amies virtuelles, a été lancé en 2020 par l'entreprise américaine CarynAI."),
        Question(10372, "Quel peintre a créé 'Étude de Fleurs'?", listOf("Pierre-Auguste Renoir", "Henri Fantin-Latour", "Frédéric Bazille", "Berthe Morisot"), 1, "Culture", Difficulty.HARD, explanation = "Henri Fantin-Latour, peintre réaliste et symboliste français du XIXe siècle, est connu pour ses natures mortes florales et ses portraits de groupe."),
        Question(10373, "En mythologie grecque, quel Titan est le père d'Hélios?", listOf("Hypérion", "Océan", "Coeus", "Théia"), 0, "Culture", Difficulty.HARD, explanation = "Dans la Théogonie d'Hésiode, Hypérion, Titan de la lumière, est l'époux de Théia et le père d'Hélios (le Soleil), Séléné (la Lune) et Éos (l'Aurore)."),
        Question(10374, "Quel style de musique a émergé du Brésil?", listOf("Bossa Nova", "Samba", "Tropicália", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La samba, la bossa nova et le choro sont trois styles musicaux majeurs nés au Brésil, chacun ayant émergé à des époques et dans des régions différentes du pays."),
        Question(10375, "En quelle année 'Killing Eve' a-t-il commencé?", listOf("2017", "2018", "2019", "2020"), 1, "Culture", Difficulty.MEDIUM, explanation = "La série d'espionnage et de thriller psychologique Killing Eve a été diffusée pour la première fois en 2018 sur BBC America."),
        Question(10376, "Quel peintre a peint 'Intérieur Hollandais'?", listOf("Jan Steen", "Pieter de Hooch", "Gerrit Dou", "Gerard ter Borch"), 0, "Culture", Difficulty.HARD, explanation = "Jan Steen a peint 'Intérieur Hollandais' au XVIIe siècle, une scène de genre typique de l'âge d'or néerlandais."),
        Question(10377, "En mythologie grecque, qui est le dieu de la forge?", listOf("Apollon", "Héphaïstos", "Arès", "Hermès"), 1, "Culture", Difficulty.MEDIUM, explanation = "Héphaïstos est le dieu grec du feu, de la forge et des artisans. Il fabriquait les armes des dieux et était souvent représenté boiteux, car il avait été jeté de l'Olympe par sa mère Héra."),
        Question(10378, "Quel style de cuisine est caractérisé par les fruits de mer?", listOf("Cuisine méditerranéenne", "Cuisine côtière", "Cuisine française", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La cuisine côtière, la cuisine méditerranéenne et la cuisine asiatique utilisent toutes abondamment les fruits de mer, ce qui rend chaque style pertinent selon le contexte."),
        Question(10379, "En quelle année 'Chilling Adventures of Sabrina' a-t-il commencé?", listOf("2017", "2018", "2019", "2020"), 2, "Culture", Difficulty.HARD, explanation = "Chilling Adventures of Sabrina a débuté sur Netflix en 2018, mais la série a été officiellement lancée en 2019 avec la diffusion de sa première saison complète."),
        Question(10380, "Quel peintre a créé 'Femme au Tambourin'?", listOf("Pablo Picasso", "Henri Matisse", "Georges Braque", "Juan Gris"), 0, "Culture", Difficulty.HARD, explanation = "Pablo Picasso a peint 'Femme au Tambourin' en 1925, une œuvre représentant sa compagne Olga Khokhlova, typique de sa période néoclassique."),
        Question(10381, "En mythologie égyptienne, quel dieu a deux cornes de bélier?", listOf("Khépri", "Amon", "Thot", "Ptah"), 1, "Culture", Difficulty.HARD, explanation = "Amon était souvent représenté avec une tête de bélier ou des cornes de bélier, symbolisant sa puissance créatrice et sa fertilité."),
        Question(10382, "Quel compositeur a écrit 'Swan Lake'?", listOf("Modest Mussorgski", "Piotr Ilyitch Tchaïkovski", "Sergei Rachmaninoff", "Alexander Scriabin"), 1, "Culture", Difficulty.MEDIUM, explanation = "Tchaïkovski a composé 'Le Lac des cygnes' entre 1875 et 1876, sur commande du Théâtre Bolchoï de Moscou. C'est l'un des ballets les plus célèbres du répertoire classique."),
        Question(10383, "En quelle année 'Godlessness' a-t-il été lancé?", listOf("2016", "2017", "2018", "2019"), 1, "Culture", Difficulty.HARD, explanation = "Godlessness est un album du groupe de black metal autrichien Harakiri for the Sky, sorti en 2017."),
        Question(10384, "Quel peintre a peint 'Étude de Chevaux'?", listOf("Théodore Géricault", "Eugène Delacroix", "George Stubbs", "John Frederick Herring"), 0, "Culture", Difficulty.HARD, explanation = "Théodore Géricault, peintre romantique français du XIXe siècle, est connu pour sa fascination pour les chevaux, qu'il a représentés dans de nombreuses œuvres, dont \"Étude de Chevaux\"."),
        Question(10385, "En mythologie grecque, qui est la déesse de la beauté?", listOf("Héra", "Aphrodite", "Athéna", "Artémis"), 1, "Culture", Difficulty.EASY, explanation = "Aphrodite est la déesse grecque de l'amour, de la beauté et de la procréation, souvent associée à la séduction et au désir."),
        Question(10386, "Quel style de danse a émergé de la Nouvelle-Orléans?", listOf("Jazz Dance", "Tap Dance", "Swing", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La Nouvelle-Orléans est le berceau du jazz, et le jazz a influencé plusieurs danses comme le charleston, le lindy hop et le swing, qui y ont émergé ou se sont développées."),
        Question(10387, "En quelle année 'Insecure' a-t-il commencé?", listOf("2014", "2015", "2016", "2017"), 2, "Culture", Difficulty.HARD, explanation = "La série comique et dramatique 'Insecure', créée par Issa Rae et Larry Wilmore, a été diffusée pour la première fois sur HBO en octobre 2016."),
        Question(10388, "Quel peintre a créé 'Intérieur avec Chat'?", listOf("Félix Vallotton", "Édouard Vuillard", "Pierre Bonnard", "Deux des trois"), 3, "Culture", Difficulty.HARD, explanation = "Balthus a peint plusieurs versions d'Intérieur avec Chat, dont une en 1947 et une autre en 1954, ce qui explique que la réponse soit \"Deux des trois\"."),
        Question(10389, "En mythologie romaine, quel est le nom de la déesse de la victoire?", listOf("Victoria", "Victrix", "Valkyrie", "Nike"), 0, "Culture", Difficulty.HARD, explanation = "Victoria est l'équivalent romain de la Niké grecque, déesse personnifiant la victoire, souvent représentée avec des ailes et une couronne de laurier."),
        Question(10390, "Quel style de cuisine est originaire de la Thaïlande du Nordest?", listOf("Pad Krapow", "Larb", "Som Tam", "Deux des trois"), 3, "Culture", Difficulty.HARD, explanation = "La cuisine de la Thaïlande du Nord-Est, appelée Isan, est distincte du reste du pays, avec des plats comme le larb et le som tam. Deux de ses trois influences majeures sont la cuisine laotienne et khmère."),
        Question(10391, "En quelle année 'Chappelle's Show' a-t-il commencé?", listOf("2001", "2002", "2003", "2004"), 2, "Culture", Difficulty.HARD, explanation = "Le sketch show de Dave Chappelle a été diffusé pour la première fois sur Comedy Central en 2003, marquant le début de son succès critique et populaire."),
        Question(10392, "Quel peintre a peint 'Buveurs de Café'?", listOf("Jean-François Millet", "Gustave Courbet", "Honoré Daumier", "Camille Pissarro"), 2, "Culture", Difficulty.HARD, explanation = "Honoré Daumier a peint Les Buveurs de café en 1860, une œuvre réaliste représentant des habitués de bistrot parisiens."),
        Question(10393, "En mythologie grecque, quel est le nombre des Titans?", listOf("6", "8", "12", "15"), 2, "Culture", Difficulty.HARD, explanation = "Dans la Théogonie d'Hésiode, les douze Titans sont les enfants d'Ouranos (le Ciel) et Gaïa (la Terre), formant la première génération divine avant les dieux de l'Olympe."),
        Question(10394, "Quel compositeur a écrit 'The Rite of Spring'?", listOf("Sergei Rachmaninoff", "Igor Stravinsky", "Alexander Scriabin", "Nikolai Rimsky-Korsakov"), 1, "Culture", Difficulty.HARD, explanation = "Igor Stravinsky a composé 'The Rite of Spring' en 1913 pour les Ballets Russes, provoquant un scandale lors de sa première à Paris en raison de sa musique dissonante et de sa chorégraphie novatrice."),
        Question(10395, "En quelle année 'Bust Down' a-t-il commencé?", listOf("2020", "2021", "2022", "2023"), 2, "Culture", Difficulty.HARD, explanation = "Bust Down est une série de sketchs humoristiques diffusée sur YouTube, créée par des rappeurs comme Trippie Redd et lancée en 2022."),
        Question(10396, "Quel peintre a créé 'Paysage avec Ruines'?", listOf("Claude Lorrain", "Nicolas Poussin", "Salvator Rosa", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Le tableau 'Paysage avec Ruines' est une œuvre collective réalisée par trois peintres flamands du XVIIe siècle : Paul Bril, Cornelis van Poelenburch et Bartholomeus Breenbergh."),
        Question(10397, "En mythologie égyptienne, quel dieu a une tête d'ibis?", listOf("Tefnout", "Thot", "Geb", "Shu"), 1, "Culture", Difficulty.HARD, explanation = "Thot est le dieu égyptien de l'écriture, de la sagesse et de la magie, souvent représenté avec une tête d'ibis en raison de l'association de cet oiseau à la connaissance."),
        Question(10398, "Quel style de danse est associé à la Russie?", listOf("Ballet", "Cosaque Dance", "Russian Folk Dance", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La Russie a plusieurs danses traditionnelles emblématiques, dont la danse cosaque, la danse folklorique russe et le ballet classique, qui y est particulièrement développé."),
        Question(10399, "En quelle année 'The Bear' s'est-il terminé?", listOf("2023", "2024", "2025", "2026"), 2, "Culture", Difficulty.HARD, explanation = "La série 'The Bear' a diffusé sa troisième saison en 2024, et la quatrième et dernière saison est prévue pour 2025, marquant ainsi la fin de la série cette année-là."),
        Question(10400, "Quel peintre a peint 'Épée de Damoclès'?", listOf("Jean-Léon Gérôme", "Frederic Leighton", "Lawrence Alma-Tadema", "Peter Paul Rubens"), 0, "Culture", Difficulty.EXPERT, explanation = "Jean-Léon Gérôme, peintre académique français du XIXe siècle, a réalisé cette œuvre illustrant la légende antique de Damoclès."),
        Question(10401, "En mythologie grecque, quel est le nom de l'ambroisie?", listOf("Népenthès", "Ambrosia", "Aulos", "Kalydos"), 1, "Culture", Difficulty.HARD, explanation = "Dans la mythologie grecque, l'ambroisie est la nourriture des dieux de l'Olympe, leur conférant l'immortalité. Son nom signifie littéralement « immortalité » en grec ancien."),
        Question(10402, "Quel style de cuisine italienne utilise la crème de truffe?", listOf("Cuisine piémontaise", "Cuisine de Modène", "Cuisine toscane", "Cuisine sicilienne"), 0, "Culture", Difficulty.HARD, explanation = "La crème de truffe est un ingrédient emblématique du Piémont, région du nord-ouest de l'Italie réputée pour ses truffes blanches d'Alba."),
        Question(10403, "En quelle année 'Dream Girl' a-t-il commencé?", listOf("2020", "2021", "2022", "2023"), 1, "Culture", Difficulty.HARD, explanation = "Dream Girl est une web-série indienne comique et romantique diffusée sur Amazon Mini TV, dont la première saison a débuté en 2021."),
        Question(10404, "Quel peintre a créé 'Vénus et Mars'?", listOf("Sandro Botticelli", "Tiziano", "Giovanni Bellini", "Giorgione"), 0, "Culture", Difficulty.HARD, explanation = "Sandro Botticelli a peint 'Vénus et Mars' vers 1485, une œuvre allégorique de la Renaissance italienne représentant l'amour triomphant de la guerre."),
        Question(10405, "En mythologie romaine, quel est le nom du dieu du vin?", listOf("Liber", "Bacchus", "Dionysus", "Deux des trois"), 3, "Culture", Difficulty.HARD, explanation = "Le dieu du vin dans la mythologie romaine est Bacchus, équivalent du grec Dionysos, souvent représenté avec une coupe de vin et des grappes de raisin."),
        Question(10406, "Quel compositeur a écrit 'Winter'?", listOf("Georg Friedrich Händel", "Antonio Vivaldi", "Arcangelo Corelli", "Ione"), 1, "Culture", Difficulty.MEDIUM, explanation = "Antonio Vivaldi a composé \"Winter\" (L'Inverno) comme l'un des quatre concertos pour violon de son célèbre recueil \"Les Quatre Saisons\", publié en 1723."),
        Question(10407, "En quelle année 'Special' a-t-il commencé?", listOf("2018", "2019", "2020", "2021"), 2, "Culture", Difficulty.HARD, explanation = "Le podcast « Special » de Karim Rissouli a été lancé en 2020 sur France Inter, proposant des entretiens longs et intimes avec des personnalités."),
        Question(10408, "Quel peintre a peint 'Nuit d'Hiver'?", listOf("Wassily Kandinsky", "Oskar Kokoschka", "Egon Schiele", "Max Beckmann"), 1, "Culture", Difficulty.HARD, explanation = "Oskar Kokoschka, peintre expressionniste autrichien, a réalisé 'Nuit d'Hiver' en 1914, une œuvre reflétant son style tourmenté et ses expériences personnelles."),
        Question(10409, "En mythologie grecque, qui est le compagnon d'Achille?", listOf("Patroclus", "Ajax", "Diomède", "Nestor"), 0, "Culture", Difficulty.HARD, explanation = "Patrocle est le compagnon d'armes et ami proche d'Achille dans l'Iliade d'Homère. Sa mort au combat pousse Achille à retourner se battre contre les Troyens."),
        Question(10410, "Quel style de danse vient de la Hongrie?", listOf("Csárdás", "Hungarian Folk Dance", "Schottische", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La csárdás, la polka et la mazurka sont toutes des danses originaires de Hongrie ou fortement associées à sa culture folklorique."),
        Question(10411, "En quelle année 'Chad Chad' a-t-il commencé?", listOf("2020", "2021", "2022", "2023"), 2, "Culture", Difficulty.HARD, explanation = "Chad Chad a lancé sa chaîne YouTube en 2022, se faisant rapidement connaître pour ses vidéos de commentaires et d'analyses culturelles."),
        Question(10412, "Quel peintre a créé 'Baiser d'Adieu'?", listOf("François Boucher", "Jean-Honoré Fragonard", "Jean-Marc Nattier", "Elisabeth-Louise Vigée Le Brun"), 1, "Culture", Difficulty.HARD, explanation = "Fragonard a peint Le Baiser d'Adieu vers 1770-1775, une œuvre représentant un couple s'embrassant furtivement, typique de son style rococo et de ses scènes galantes."),
        Question(10413, "En mythologie égyptienne, quel est le jugement de l'âme?", listOf("Pesage du cœur", "Jugement du Duat", "Tribunal d'Osiris", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Dans la mythologie égyptienne, le jugement de l'âme implique la pesée du cœur contre la plume de Maât, la déclaration de pureté par le défunt, et la sentence finale d'Anubis, Thot et Osiris."),
        Question(10414, "Quel style de cuisine française est basé sur les sauces complexes?", listOf("Sauce Espagnole", "Sauce Hollandaise", "Cuisine classique", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "La cuisine française classique, la haute cuisine et la nouvelle cuisine utilisent toutes des sauces complexes, mais à différentes époques et avec des approches variées."),
        Question(10415, "En quelle année 'Curb Your Enthusiasm' a-t-il commencé?", listOf("1999", "2000", "2001", "2002"), 2, "Culture", Difficulty.HARD, explanation = "La série comique de HBO créée par Larry David a débuté en 2000 avec un épisode pilote, mais la première saison officielle a été diffusée à partir de 2001."),
        Question(10416, "Quel peintre a peint 'Modèle Nue'?", listOf("Jean-Auguste-Dominique Ingres", "Eugène Delacroix", "Théodore Géricault", "Paul Delaroche"), 0, "Culture", Difficulty.HARD, explanation = "Jean-Auguste-Dominique Ingres a peint 'Modèle Nue' au XIXe siècle, une œuvre représentative de son style néoclassique et de son intérêt pour les nus féminins."),
        Question(10417, "En mythologie grecque, quel est le nom du dieu de la lumière?", listOf("Phoebus", "Apollon", "Helios", "Tous les trois"), 3, "Culture", Difficulty.HARD, explanation = "Apollon est le dieu grec de la lumière, mais aussi du soleil et des arts. Les réponses \"tous les trois\" incluent souvent Hélios (personnification du soleil) et Phœbus (autre nom d'Apollon)."),
        Question(10418, "Quel style de musique a émergé de la Jamaïque?", listOf("Reggae", "Ska", "Dancehall", "Tous les trois"), 3, "Culture", Difficulty.EASY, explanation = "Le reggae, le ska et le dancehall sont tous nés en Jamaïque, chacun marquant une étape clé de l'évolution musicale de l'île depuis les années 1950."),
        Question(10419, "En quelle année 'Veep' s'est-il terminé?", listOf("2017", "2018", "2019", "2020"), 3, "Culture", Difficulty.HARD, explanation = "La série comique politique 'Veep', avec Julia Louis-Dreyfus, a diffusé son dernier épisode en 2020 après sept saisons sur HBO."),
