        Question(10424, "Quel peintre a peint 'Clair de Lune'?", listOf("Caspar David Friedrich", "Joseph Anton Koch", "Ferdinand Oliver", "John Constable"), 0, "Culture", Difficulty.HARD, explanation = "Caspar David Friedrich, peintre romantique allemand du XIXe siècle, a réalisé 'Clair de Lune' (ou 'Mondaufgang am Meer'), une œuvre emblématique de son style contemplatif de la nature."),
