        Question(10441, "En mythologie grecque, qui est la mère de Héraclès?", listOf("Alcmène", "Sémélé", "Léda", "Io"), 0, "Culture", Difficulty.HARD, explanation = "Alcmène, une mortelle de la lignée de Persée, est la mère d'Héraclès après que Zeus l'a séduite en prenant l'apparence de son mari Amphitryon."),
